	DATEFMT_MMDDYYYY = 1,
	DATEFMT_DDMMYYYY,
	DATEFMT_YYYYMMDD,
	DATEFMT_ISO,
	DATEFMT_MAX
};

/* Simple integer / time list. */
struct ilist {
	long *v;
	int n, cap;
};

struct rpt {
	enum recur_type type;
	int freq;
	time_t until;
	struct ilist bymonth;
	struct ilist bywday;
	struct ilist bymonthday;
	struct ilist exc;	/* exception days (midnight) */
};

struct apoint {
	time_t start;
	long dur;
	char state;
	char *mesg;
	char *note;
};

