	struct rpt rpt;
	int id;
	time_t day;
	char *mesg;
	char *note;
};

struct todo {
	char *mesg;
	int id;		/* priority */
	int completed;
	char *note;
};

/* Generic list of pointers. */
struct plist {
	void **v;
	int n, cap;
};

struct item_filter {
	int invert;
	int type_mask;
	char *hash;
	regex_t *regex;
	time_t start_from;
	time_t start_to;
	time_t end_from;
	time_t end_to;
	int priority;
	int completed;
	int uncompleted;
};

struct conf {
	int auto_save;
	int auto_gc;
	int periodic_save;
	int systemevents;
	int confirm_quit;
	int confirm_delete;
	int system_dialogs;
	int progress_bar;
	int multiple_days;
	int compact_panels;
	int default_panel;
	int calendar_view;
	int layout;
	int sidebar_width;
	int todo_view;
	int heading_pos;
	int header_line;
	int event_separator;
	int day_separator;
	int empty_appt_line;
	char empty_day[BUFSIZ_];
	int notify_bar;
	char theme[BUFSIZ_];
	int daemon_enable;
	int daemon_log;
	int input_datefmt;
	char output_datefmt[BUFSIZ_];
	char day_heading[BUFSIZ_];
	char notify_date[BUFSIZ_];
	char notify_time[BUFSIZ_];
	char notify_cmd[BUFSIZ_];
	int notify_all;
	int notify_warning;
