void *xmalloc(size_t);
void *xcalloc(size_t, size_t);
void *xrealloc(void *, size_t);
char *xstrdup(const char *);
void exit_msg(const char *file, int line, const char *fmt, ...)
	__attribute__((noreturn));
#define EXIT(...) exit_msg(__FILE_NAME_, __LINE_NO_, __VA_ARGS__)
void fatal_plain(const char *fmt, ...) __attribute__((noreturn));
void ilist_add(struct ilist *, long);
void ilist_free(struct ilist *);
int ilist_has(struct ilist *, long);
