		       struct recur_event *rev);
void print_todo(const char *format, struct todo *todo);
void print_notefile(FILE *out, const char *filename, int nbtab);
char *apoint_tostr(struct apoint *);
char *event_tostr(struct event *);
char *recur_apoint_tostr(struct recur_apoint *);
char *recur_event_tostr(struct recur_event *);
char *todo_tostr(struct todo *);
char *apoint_hash(struct apoint *);
char *event_hash(struct event *);
char *recur_apoint_hash(struct recur_apoint *);
char *recur_event_hash(struct recur_event *);
char *todo_hash(struct todo *);
int io_file_exists(const char *);
char *mkpath(const char *dir, const char *file);

/* sha1.c */
void sha1_digest(const char *data, size_t len, char *hex /* 41 bytes */);
int sha1_stream(FILE *fp, char *hex);

/* items.c */
int apoint_cmp(void *, void *);
int event_cmp(void *, void *);
int recur_apoint_cmp(void *, void *);
int recur_event_cmp(void *, void *);
int todo_cmp(void *, void *);
struct apoint *apoint_new(const char *mesg, const char *note, time_t start,
			  long dur, char state);
struct event *event_new(const char *mesg, const char *note, time_t day, int id);
struct recur_apoint *recur_apoint_new(const char *mesg, const char *note,
				      time_t start, long dur, char state,
				      struct rpt *rpt);
struct recur_event *recur_event_new(const char *mesg, const char *note,
				    time_t day, int id, struct rpt *rpt);
struct todo *todo_new(const char *mesg, int id, int completed, const char *note);
void apoint_write(struct apoint *, FILE *);
void event_write(struct event *, FILE *);
void recur_apoint_write(struct recur_apoint *, FILE *);
void recur_event_write(struct recur_event *, FILE *);
void todo_write(struct todo *, FILE *);
int apoint_inday(struct apoint *, time_t day);
int event_inday(struct event *, time_t day);
int filter_apoint(struct item_filter *, struct apoint *);
int filter_event(struct item_filter *, struct event *);
int filter_recur_apoint(struct item_filter *, struct recur_apoint *);
int filter_recur_event(struct item_filter *, struct recur_event *);
int filter_todo(struct item_filter *, struct todo *);

/* recur.c */
void rpt_init(struct rpt *);
void rpt_copy(struct rpt *dst, struct rpt *src);
void rpt_free(struct rpt *);
int recur_char2def(char c);
char recur_def2char(int type);
const char *recur_valid(struct rpt *rpt, time_t start);
int recur_isocc_day(time_t start, struct rpt *rpt, time_t day);
int recur_find_occurrence(time_t start, long dur, struct rpt *rpt,
			  time_t day, time_t *occurrence);
int recur_next_occurrence(time_t start, long dur, struct rpt *rpt,
			  time_t occ_day, time_t *next_day, int skip_exc);
