int recur_event_find_occurrence(struct recur_event *, time_t day,
				time_t *occurrence);
void rpt_write(struct rpt *, FILE *, int is_event);
int rpt_has_by(struct rpt *);

/* io.c */
void io_init(const char *cfile, const char *datadir, const char *confdir);
void io_check_dir(const char *);
int io_check_file(const char *);
void io_check_data_files(void);
void io_load_app(struct item_filter *);
void io_load_todo(struct item_filter *);
void io_load_data(struct item_filter *, int force);
int io_save_apts(const char *);
int io_save_todo(const char *);
int io_save_cal(void);
void io_save_mutex? ;
void io_load_error(const char *path, unsigned line, const char *msg)
