/* Date helpers. */
int is_leap(int y)
{
	return (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
}

int days_in_month(int y, int m)
{
	static const int dm[] =
		{ 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
	if (m < 1 || m > 12)
		return 0;
	return dm[m - 1] + (m == 2 && is_leap(y));
}

int check_date(int y, int m, int d)
{
	return y >= 1 && m >= 1 && m <= 12 && d >= 1 &&
	       d <= days_in_month(y, m);
}

int check_time(int h, int m)
{
	return h >= 0 && h < 24 && m >= 0 && m < 60;
}

time_t date2sec(int y, int m, int d, int hour, int min)
{
	struct tm t;

	memset(&t, 0, sizeof(t));
	t.tm_year = y - 1900;
	t.tm_mon = m - 1;
	t.tm_mday = d;
	t.tm_hour = hour;
	t.tm_min = min;
	t.tm_sec = 0;
	t.tm_isdst = -1;
	return mktime(&t);
}

time_t update_time_in_date(time_t date, int hr, int mn)
{
	struct tm lt;

	localtime_r(&date, &lt);
	lt.tm_hour = hr;
	lt.tm_min = mn;
	lt.tm_sec = 0;
	lt.tm_isdst = -1;
	return mktime(&lt);
}

time_t get_today(void)
{
	time_t now = time(NULL);
	return update_time_in_date(now, 0, 0);
}

time_t date_sec_change(time_t date, int delta_month, int delta_day)
{
	struct tm lt;

	localtime_r(&date, &lt);
	lt.tm_mon += delta_month;
	lt.tm_mday += delta_day;
	lt.tm_isdst = -1;
	return mktime(&lt);
}

/*
 * Parse a numeric date in the given format.  Returns 1 on success.
 */
int parse_date(const char *s, int datefmt, int *year, int *month, int *day)
{
	const char sep = (datefmt == DATEFMT_ISO) ? '-' : '/';
	const char *p;
	long in[3] = { 0, 0, 0 };
	int n = 0;
	long y, m, d;

	if (!s)
		return 0;
	for (p = s; *p; p++) {
		if (*p == sep) {
			if (++n > 2)
				return 0;
		} else if (*p >= '0' && *p <= '9') {
			in[n] = in[n] * 10 + (*p - '0');
			if (in[n] > 100000000)
				in[n] = 100000000;
		} else {
			return 0;
		}
	}
	if (n < 2 || in[n] == 0)
		return 0;

	switch (datefmt) {
	case DATEFMT_MMDDYYYY:
		m = in[0];
		d = in[1];
		y = in[2];
		break;
	case DATEFMT_DDMMYYYY:
		d = in[0];
		m = in[1];
		y = in[2];
		break;
	case DATEFMT_YYYYMMDD:
	case DATEFMT_ISO:
		y = in[0];
		m = in[1];
		d = in[2];
		break;
	default:
		return 0;
	}
	if (y > 1000000)
		return 0;
	if (!check_date((int)y, (int)m, (int)d))
		return 0;
	*year = (int)y;
	*month = (int)m;
	*day = (int)d;
	return 1;
}

int parse_time(const char *s, int *hour, int *minute)
{
	const char *p;
	long in[2] = { 0, 0 };
	int n = 0;

	if (!s)
		return 0;
	for (p = s; *p; p++) {
		if (*p == ':') {
			if (++n > 1)
				return 0;
		} else if (*p >= '0' && *p <= '9') {
			in[n] = in[n] * 10 + (*p - '0');
			if (in[n] > 100000)
				in[n] = 100000;
		} else {
			return 0;
		}
	}
	if (n == 0 && strlen(s) == 4) {
		in[1] = in[0] % 100;
		in[0] = in[0] / 100;
		n = 1;
	}
	if (n != 1 || in[0] >= 24 || in[1] >= 60)
		return 0;
	*hour = (int)in[0];
	*minute = (int)in[1];
	return 1;
}

void format_date_numeric(char *buf, size_t n, time_t t, int datefmt)
{
	struct tm lt;
	localtime_r(&t, &lt);
	switch (datefmt) {
	case DATEFMT_DDMMYYYY:
		snprintf(buf, n, "%02d/%02d/%04d", lt.tm_mday, lt.tm_mon + 1,
			 lt.tm_year + 1900);
		break;
	case DATEFMT_YYYYMMDD:
		snprintf(buf, n, "%04d/%02d/%02d", lt.tm_year + 1900,
			 lt.tm_mon + 1, lt.tm_mday);
		break;
	case DATEFMT_ISO:
		snprintf(buf, n, "%04d-%02d-%02d", lt.tm_year + 1900,
			 lt.tm_mon + 1, lt.tm_mday);
		break;
	default:
		snprintf(buf, n, "%02d/%02d/%04d", lt.tm_mon + 1, lt.tm_mday,
			 lt.tm_year + 1900);
		break;
	}
}

char *mkpath(const char *dir, const char *file)
{
	size_t n = strlen(dir) + strlen(file) + 2;
	char *p = xmalloc(n);
	snprintf(p, n, "%s/%s", dir, file);
	return p;
}

/*
 * Format strings.
 */
enum format_specifier {
	FS_STARTDATE,
	FS_DURATION,
	FS_ENDDATE,
	FS_REMAINING,
	FS_MESSAGE,
	FS_NOTE,
	FS_NOTEFILE,
	FS_PRIORITY,
	FS_RAW,
	FS_HASH,
	FS_PSIGN,
	FS_EOF,
	FS_UNKNOWN
};

#define FS_EXT_MAXLEN 64

static enum format_specifier parse_fs(const char **s, char *extformat)
{
	char buf[FS_EXT_MAXLEN];
	int i;

	extformat[0] = '\0';

	switch (**s) {
	case 's':
		strcpy(extformat, "epoch");
		return FS_STARTDATE;
	case 'S':
		return FS_STARTDATE;
	case 'd':
		return FS_DURATION;
	case 'e':
		strcpy(extformat, "epoch");
		return FS_ENDDATE;
	case 'E':
		return FS_ENDDATE;
	case 'r':
		return FS_REMAINING;
	case 'm':
		return FS_MESSAGE;
	case 'n':
		return FS_NOTEFILE;
	case 'N':
		return FS_NOTE;
	case 'p':
		return FS_PRIORITY;
	case '%':
		return FS_PSIGN;
	case '\0':
		return FS_EOF;
	case '(':
		for ((*s)++, i = 0; **s != ':' && **s != ')'; (*s)++, i++) {
			if (**s == '\0')
				return FS_EOF;
			if (i < FS_EXT_MAXLEN)
				buf[i] = **s;
		}
		buf[(i < FS_EXT_MAXLEN) ? i : FS_EXT_MAXLEN - 1] = '\0';

		if (**s == ':') {
			for ((*s)++, i = 0; **s != ')'; (*s)++, i++) {
				if (**s == '\0')
					return FS_EOF;
				if (i < FS_EXT_MAXLEN)
					extformat[i] = **s;
			}
			extformat[(i < FS_EXT_MAXLEN) ? i :
				  FS_EXT_MAXLEN - 1] = '\0';
		}

		if (!strcmp(buf, "start"))
			return FS_STARTDATE;
		else if (!strcmp(buf, "duration"))
			return FS_DURATION;
		else if (!strcmp(buf, "end"))
			return FS_ENDDATE;
		else if (!strcmp(buf, "remaining"))
			return FS_REMAINING;
		else if (!strcmp(buf, "message"))
			return FS_MESSAGE;
		else if (!strcmp(buf, "noteid"))
			return FS_NOTEFILE;
		else if (!strcmp(buf, "note"))
			return FS_NOTE;
		else if (!strcmp(buf, "priority"))
			return FS_PRIORITY;
		else if (!strcmp(buf, "raw"))
			return FS_RAW;
		else if (!strcmp(buf, "hash"))
			return FS_HASH;
		else
			return FS_UNKNOWN;
	default:
		return FS_UNKNOWN;
	}
}

/* Handle a backslash escape; returns 0 if the format string ended. */
static int print_escape(const char **p)
{
	(*p)++;
	switch (**p) {
	case '\0':
		return 0;
	case 'a':
		putchar('\a');
		break;
	case 'b':
		putchar('\b');
		break;
	case 'f':
		putchar('\f');
		break;
	case 'n':
		putchar('\n');
		break;
	case 'r':
		putchar('\r');
		break;
	case 't':
		putchar('\t');
		break;
	case 'v':
		putchar('\v');
		break;
	case '\\':
		putchar('\\');
		break;
	case '\'':
		putchar('\'');
		break;
	case '"':
		putchar('"');
		break;
	case '?':
		putchar('?');
		break;
	case '0':
		putchar('\0');
		break;
	default:
		break;
	}
	return 1;
}

static void print_date(time_t date, time_t day, const char *extformat)
{
	char buf[BUFSIZ_];
	struct tm lt;

	if (!strcmp(extformat, "epoch")) {
		printf("%ld", (long)date);
		return;
	}
	localtime_r(&date, &lt);
	if (extformat[0] == '\0' || !strcmp(extformat, "default")) {
		time_t day_end = date_sec_change(day, 0, 1);
		if (date >= day && date <= day_end)
			strftime(buf, sizeof(buf), "%H:%M", &lt);
		else
			strcpy(buf, "..:..");
	} else {
		buf[0] = '\0';
		strftime(buf, sizeof(buf), extformat, &lt);
	}
	fputs(buf, stdout);
}

static void print_datediff(long dur, const char *fmt)
{
	const char *p;
	long val;
	int pad, ext;

	for (p = fmt; *p; p++) {
		if (*p != '%') {
			putchar(*p);
			continue;
		}
		p++;
		pad = 1;
		ext = 0;
		if (*p == '-') {
			pad = 0;
			p++;
		}
		if (*p == 'E') {
			ext = 1;
			p++;
		}
		switch (*p) {
		case '\0':
			return;
		case 'd':
			val = dur / DAYINSEC;
			break;
		case 'H':
			val = ext ? dur / HOURINSEC : (dur / HOURINSEC) % 24;
			break;
		case 'M':
			val = ext ? dur / MININSEC : (dur / MININSEC) % 60;
			break;
		case 'S':
			val = ext ? dur : dur % 60;
			break;
		case '%':
			putchar('%');
			continue;
		default:
			putchar('?');
			continue;
		}
		if (pad)
			printf("%02ld", val);
		else
			printf("%ld", val);
	}
}

static void print_duration(long dur, char *extformat)
{
	if (extformat[0] == '\0' || !strcmp(extformat, "epoch"))
		printf("%ld", dur);
	else
		print_datediff(dur, extformat);
}

static void print_remaining(time_t start, char *extformat)
{
	long rem = (long)(start - time(NULL));
	if (extformat[0] == '\0')
		strcpy(extformat, "%EH:%M");
	print_datediff(rem, extformat);
}

void print_notefile(FILE *out, const char *filename, int nbtab)
{
	char path[BUFSIZ_ * 4];
	char linestarter[BUFSIZ_];
	char buffer[BUFSIZ_ * 4];
	FILE *fp;
	int i, printlinestarter = 1;

	if (nbtab < BUFSIZ_) {
		for (i = 0; i < nbtab; i++)
			linestarter[i] = '\t';
		linestarter[nbtab] = '\0';
	} else {
		linestarter[0] = '\0';
	}

	snprintf(path, sizeof(path), "%s/%s", path_notes,
		 filename ? filename : "(null)");
	fp = fopen(path, "r");
	if (fp) {
		while (fgets(buffer, sizeof(buffer), fp) != NULL) {
			if (printlinestarter) {
				fputs(linestarter, out);
				printlinestarter = 0;
			}
			fputs(buffer, out);
			if (buffer[0] && buffer[strlen(buffer) - 1] == '\n')
				printlinestarter = 1;
		}
		fputs("\n", out);
		fclose(fp);
	} else {
		fputs(linestarter, out);
		fputs("No note file found\n", out);
	}
}

static void print_str(const char *s)
{
	fputs(s ? s : "(null)", stdout);
}

static void print_hash_of(char *raw)
{
	char *h = item_hash(raw);
	fputs(h, stdout);
	free(h);
}

