{"command":"cat > /workspace/src/recur.c <<'EOF'
#include "calcurse.h"
#include <limits.h>

/*
 * Civil day arithmetic.  A day is represented by the number of days since
 * 1970-01-01 (proleptic Gregorian calendar).
 */
static long days_from_civil(long y, int m, int d)
{
	long era, yoe, doy, doe;
	y -= m <= 2;
	era = (y >= 0 ? y : y - 399) / 400;
	yoe = y - era * 400;
	doy = (153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + d - 1;
	doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
	return era * 146097 + doe - 719468;
}

static void civil_from_days(long z, int *py, int *pm, int *pd)
{
	long era, doe, yoe, y, doy, mp, d, m;
	z += 719468;
	era = (z >= 0 ? z : z - 146096) / 146097;
	doe = z - era * 146097;
	yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
	y = yoe + era * 400;
	doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
	mp = (5 * doy + 2) / 153;
	d = doy - (153 * mp + 2) / 5 + 1;
	m = mp + (mp < 10 ? 3 : -9);
	*py = (int)(y + (m <= 2));
	*pm = (int)m;
	*pd = (int)d;
}

static int weekday(long z)
{
	long w = (z + 4) % 7;
	if (w < 0)
		w += 7;
	return (int)w;
}

static long civil_of_time(time_t t)
{
	struct tm lt;
	localtime_r(&t, &lt);
	return days_from_civil(lt.tm_year + 1900L, lt.tm_mon + 1, lt.tm_mday);
}

void rpt_init(struct rpt *r)
{
	memset(r, 0, sizeof(*r));
}

void rpt_copy(struct rpt *dst, struct rpt *src)
{
	dst->type = src->type;
	dst->freq = src->freq;
	dst->until = src->until;
	ilist_copy(&dst->bymonth, &src->bymonth);
	ilist_copy(&dst->bywday, &src->bywday);
	ilist_copy(&dst->bymonthday, &src->bymonthday);
	ilist_copy(&dst->exc, &src->exc);
}

void rpt_free(struct rpt *r)
{
	ilist_free(&r->bymonth);
	ilist_free(&r->bywday);
	ilist_free(&r->bymonthday);
	ilist_free(&r->exc);
}

int rpt_has_by(struct rpt *r)
{
	return r->bymonth.n || r->bywday.n || r->bymonthday.n;
}

int recur_char2def(char c)
{
	switch (c) {
	case 'D':
		return RECUR_DAILY;
	case 'W':
		return RECUR_WEEKLY;
	case 'M':
		return RECUR_MONTHLY;
	case 'Y':
		return RECUR_YEARLY;
	default:
		die_at("recur.c", 433, "unknown character");
	}
}

char recur_def2char(int type)
{
	switch (type) {
	case RECUR_DAILY:
		return 'D';
	case RECUR_WEEKLY:
		return 'W';
	case RECUR_MONTHLY:
		return 'M';
	case RECUR_YEARLY:
		return 'Y';
	default:
		return '?';
	}
}

/*
 * Recurrence context: the start of an item and its rule in civil terms.
 */
struct rctx {
	struct rpt *r;
	long s;			/* start day */
	int sy, sm, sd, swd;
	int hh, mi, ss;
	long until;		/* LONG_MAX if none */
	long *exc;
	int nexc;
};

static void rctx_init(struct rctx *c, time_t start, struct rpt *r)
{
	struct tm lt;
	int i;

	localtime_r(&start, &lt);
	c->r = r;
	c->sy = lt.tm_year + 1900;
	c->sm = lt.tm_mon + 1;
	c->sd = lt.tm_mday;
	c->hh = lt.tm_hour;
	c->mi = lt.tm_min;
	c->ss = lt.tm_sec;
	c->s = days_from_civil(c->sy, c->sm, c->sd);
	c->swd = weekday(c->s);
	c->until = r->until ? civil_of_time(r->until) : LONG_MAX;
	c->nexc = r->exc.n;
	c->exc = c->nexc ? xmalloc(sizeof(long) * c->nexc) : NULL;
	for (i = 0; i < c->nexc; i++)
		c->exc[i] = civil_of_time((time_t)r->exc.v[i]);
}

static void rctx_free(struct rctx *c)
{
	free(c->exc);
}

static int list_has(struct ilist *l, long v)
{
	return ilist_has(l, v);
}

static int match_mday(struct ilist *l, int y, int m, int d)
{
	int i, dim = days_in_month(y, m);
	for (i = 0; i < l->n; i++) {
		long v = l->v[i];
		if (v > 0 && v == d)
			return 1;
		if (v < 0 && dim + v + 1 == d)
			return 1;
	}
	return 0;
}

static void decode_wday(long w, int *n, int *wd)
{
	if (w >= 0) {
		*n = (int)(w / 7);
		*wd = (int)(w % 7);
	} else {
		*n = -(int)((-w) / 7);
		*wd = (int)((-w) % 7);
	}
}

static int wday_match_plain(struct ilist *l, int wd)
{
	int i, n, w;
	for (i = 0; i < l->n; i++) {
		decode_wday(l->v[i], &n, &w);
		if (w == wd)
			return 1;
	}
	return 0;
}

static int wday_match_month(struct ilist *l, int y, int m, int d, int wd)
{
	int i, n, w, dim = days_in_month(y, m);
	for (i = 0; i < l->n; i++) {
		decode_wday(l->v[i], &n, &w);
		if (w != wd)
			continue;
		if (n == 0)
			return 1;
		if (n > 0 && (d - 1) / 7 + 1 == n)
			return 1;
		if (n < 0 && (dim - d) / 7 + 1 == -n)
			return 1;
	}
	return 0;
}

static int wday_match_year(struct ilist *l, int y, int yday0, int wd,
			   int limit)
{
	int i, n, w, diy = is_leap(y) ? 366 : 365;
	for (i = 0; i < l->n; i++) {
		decode_wday(l->v[i], &n, &w);
		if (w != wd)
			continue;
		if (n == 0)
			return 1;
		if (!limit) {
			if (n > 0 && yday0 / 7 + 1 == n)
				return 1;
			if (n < 0 && (diy - 1 - yday0) / 7 + 1 == -n)
				return 1;
		} else {
			if (n > 0 && yday0 / 7 == n)
				return 1;
			if (n < 0 && (diy - 1 - yday0) / 7 + 2 == -n)
				return 1;
		}
	}
	return 0;
}

static long week_start(long z)
{
	int fdow = conf.first_day_of_week ? 1 : 0;
	return z - ((weekday(z) - fdow + 7) % 7);
}

static long lmod(long a, long b)
{
	long r = a % b;
	return r < 0 ? r + b : r;
}

static int period_active(struct rctx *c, long z, int y, int m)
{
	struct rpt *r = c->r;
	long freq = r->freq;

	if (freq <= 0)
		freq = 1;
	switch (r->type) {
	case RECUR_DAILY:
		return lmod(z - c->s, freq) == 0;
	case RECUR_WEEKLY:
		return lmod((week_start(z) - week_start(c->s)) / 7, freq) == 0;
	case RECUR_MONTHLY:
		return lmod((y * 12L + m) - (c->sy * 12L + c->sm), freq) == 0;
	case RECUR_YEARLY:
		return lmod((long)y - c->sy, freq) == 0;
	}
	return 0;
}

/* Is day z a candidate occurrence (ignoring until and exceptions)? */
static int candidate(struct rctx *c, long z)
{
	struct rpt *r = c->r;
	int y, m, d, wd;

	if (z < c->s)
		return 0;
	civil_from_days(z, &y, &m, &d);
	if (!period_active(c, z, y, m))
		return 0;
	if (r->bymonth.n && !list_has(&r->bymonth, m)) {
		if (!(r->type == RECUR_YEARLY && 0))
			return 0;
	}
	wd = weekday(z);

	switch (r->type) {
	case RECUR_DAILY:
		if (r->bymonthday.n && !match_mday(&r->bymonthday, y, m, d))
			return 0;
		if (r->bywday.n && !wday_match_plain(&r->bywday, wd))
			return 0;
		return 1;
	case RECUR_WEEKLY:
		if (r->bywday.n)
			return wday_match_plain(&r->bywday, wd);
		return wd == c->swd;
	case RECUR_MONTHLY:
		if (r->bymonthday.n) {
			if (!match_mday(&r->bymonthday, y, m, d))
				return 0;
			if (r->bywday.n)
				return wday_match_month(&r->bywday, y, m, d,
							wd);
			return 1;
		}
		if (r->bywday.n)
			return wday_match_month(&r->bywday, y, m, d, wd);
		return d == c->sd;
	case RECUR_YEARLY:
		if (r->bymonthday.n) {
			if (!r->bymonth.n && m != c->sm)
				return 0;
			if (!match_mday(&r->bymonthday, y, m, d))
				return 0;
			if (r->bywday.n) {
				if (r->bymonth.n)
					return wday_match_month(&r->bywday, y,
								m, d, wd);
				return wday_match_year(&r->bywday, y,
					(int)(z - days_from_civil(y, 1, 1)),
					wd, 1);
			}
			return 1;
		}
		if (r->bywday.n) {
			if (r->bymonth.n)
				return wday_match_month(&r->bywday, y, m, d,
							wd);
			return wday_match_year(&r->bywday, y,
				(int)(z - days_from_civil(y, 1, 1)), wd, 0);
		}
		if (r->bymonth.n)
			return d == c->sd;
		return m == c->sm && d == c->sd;
	}
	return 0;
}

static int is_exc(struct rctx *c, long z)
{
	int i;
	for (i = 0; i < c->nexc; i++)
		if (c->exc[i] == z)
			return 1;
	return 0;
}

static int valid(struct rctx *c, long z)
{
	return candidate(c, z) && z <= c->until && !is_exc(c, z);
}

static time_t occ_time(struct rctx *c, long z)
{
	int y, m, d;
	struct tm t;

	civil_from_days(z, &y, &m, &d);
	memset(&t, 0, sizeof(t));
	t.tm_year = y - 1900;
	t.tm_mon = m - 1;
	t.tm_mday = d;
	t.tm_hour = c->hh;
	t.tm_min = c->mi;
	t.tm_sec = c->ss;
	t.tm_isdst = -1;
	return mktime(&t);
}

/* First and last day of the period containing day z. */
static void period_bounds(struct rctx *c, long z, long *ps, long *pe)
{
	int y, m, d;
	civil_from_days(z, &y, &m, &d);
	switch (c->r->type) {
	case RECUR_WEEKLY:
		*ps = week_start(z);
		*pe = *ps + 6;
		break;
	case RECUR_MONTHLY:
		*ps = days_from_civil(y, m, 1);
		*pe = *ps + days_in_month(y, m) - 1;
		break;
	case RECUR_YEARLY:
		*ps = days_from_civil(y, 1, 1);
		*pe = days_from_civil(y, 12, 31);
		break;
	default:
		*ps = *pe = z;
	}
}

/* Is the item start day an occurrence according to its rule? */
int recur_candidate(time_t start, struct rpt *rpt, time_t day)
{
	struct rctx c;
	int ret;
	rctx_init(&c, start, rpt);
	ret = candidate(&c, civil_of_time(day)) &&
	      civil_of_time(day) <= c.until;
	rctx_free(&c);
	return ret;
}

int recur_item_find_occurrence(time_t start, long dur, struct rpt *rpt,
			       time_t day, time_t *occurrence)
{
	struct rctx c;
	long D, z, ps, pe;
	int ret = 0;

	rctx_init(&c, start, rpt);
	D = civil_of_time(day);
	if (D < c.s)
		goto done;

	if (rpt->type == RECUR_DAILY) {
		long freq = rpt->freq > 0 ? rpt->freq : 1;
		z = D - lmod(D - c.s, freq);
		if (!candidate(&c, z) || z > c.until || is_exc(&c, z))
			goto done;
		{
			time_t o = occ_time(&c, z);
			if (z == D || o + dur > day) {
				if (occurrence)
					*occurrence = o;
				ret = 1;
			}
		}
		goto done;
	}

	z = D;
	for (;;) {
		long a, b, x;
		int found = 0;

		period_bounds(&c, z, &ps, &pe);
		if (pe < c.s)
			break;
		a = ps < c.s ? c.s : ps;
		b = pe < D ? pe : D;
		for (x = a; x <= b; x++) {
			time_t o;
			if (!candidate(&c, x))
				continue;
			found = 1;
			if (x > c.until || is_exc(&c, x))
				continue;
			o = occ_time(&c, x);
			if (x == D || o + dur > day) {
				if (occurrence)
					*occurrence = o;
				ret = 1;
				goto done;
			}
		}
		if (found)
			break;
		z = ps - 1;
	}
done:
	rctx_free(&c);
	return ret;
}

int recur_apoint_find_occurrence(struct recur_apoint *r, time_t day,
				 time_t *occurrence)
{
	return recur_item_find_occurrence(r->start, r->dur, &r->rpt, day,
					  occurrence);
}

int recur_event_find_occurrence(struct recur_event *r, time_t day,
				time_t *occurrence)
{
	return recur_item_find_occurrence(r->day, 0, &r->rpt, day,
					  occurrence);
}

#define SCAN_LIMIT (400L * 366L)

/*
 * Find the next occurrence strictly after day 'day'.  Returns the
 * occurrence time (start of day + item time) in *next.
 */
int recur_next_occurrence(time_t start, struct rpt *rpt, time_t day,
			  time_t *next, int ignore_until, int skip_exc)
{
	struct rctx c;
	long z, lim;
	int ret = 0;

	rctx_init(&c, start, rpt);
	z = civil_of_time(day) + 1;
	if (z < c.s)
		z = c.s;
	for (lim = 0; lim < SCAN_LIMIT; lim++, z++) {
		if (!ignore_until && z > c.until)
			break;
		if (!candidate(&c, z))
			continue;
		if (skip_exc && is_exc(&c, z))
			continue;
		*next = occ_time(&c, z);
		ret = 1;
		break;
	}
	rctx_free(&c);
	return ret;
}

/* Find the n-th occurrence (1-based, exceptions skipped, until ignored). */
int recur_nth_occurrence(time_t start, struct rpt *rpt, int n, time_t *nth)
{
	struct rctx c;
	long z, lim;
	int k = 0, ret = 0;

	rctx_init(&c, start, rpt);
	z = c.s;
	for (lim = 0; lim < SCAN_LIMIT * 4; lim++, z++) {
		if (!candidate(&c, z) || is_exc(&c, z))
			continue;
		if (++k == n) {
			*nth = occ_time(&c, z);
			ret = 1;
			break;
		}
	}
	rctx_free(&c);
	return ret;
}

long recur_apoint_end(struct recur_apoint *r)
{
	return r->start + r->dur;
}
