static int check_month_scan(struct rpt *rpt, long v)
{
	(void)rpt;
	return v >= 1 && v <= 12;
}

static void exc_scan(struct ilist *exc, FILE *fp)
{
	int c, m, d, y;
	struct tm day;

	while ((c = getc(fp)) == '!') {
		ungetc(c, fp);
		if (fscanf(fp, "!%d / %d / %d ", &m, &d, &y) != 3)
			die_at("recur.c", 1701, "syntax error in item date");
		if (!check_date(y, m, d))
			die_at("recur.c", 1704, "date error in item exception");
		memset(&day, 0, sizeof(day));
		day.tm_year = y - 1900;
		day.tm_mon = m - 1;
		day.tm_mday = d;
		day.tm_isdst = -1;
		{
			time_t t = mktime(&day);
			/* sorted insertion (stable) */
			int i, pos = exc->n;
			ilist_add(exc, 0);
			for (i = 0; i < exc->n - 1; i++) {
				if ((time_t)exc->v[i] > t) {
					pos = i;
					break;
				}
			}
			for (i = exc->n - 1; i > pos; i--)
				exc->v[i] = exc->v[i - 1];
			exc->v[pos] = (long)t;
		}
	}
	ungetc(c, fp);
}

static void read_desc(FILE *fp, char *buf, size_t n, const char *path,
		      unsigned line)
{
	char *nl;
	if (!fgets(buf, (int)n, fp))
		io_load_error(path, line, "error in appointment description");
	nl = strchr(buf, '\n');
	if (nl)
		*nl = '\0';
}

void io_load_app(struct item_filter *filter)
{
	FILE *fp;
	int c, is_appointment, is_event, is_recursive;
	int sm, sd, sy, sh, smin, em, ed, ey, eh, emin;
	int um, ud, uy;
	int id = 0;
	char type, state = 0;
	char note[MAX_NOTESIZ + 1], *notep;
	unsigned line = 0;
	static char buf[16384];
	struct rpt rpt;

	fp = fopen(path_apts, "r");
	if (!fp)
		die_at("io.c", 569, "failed to open appointment file");

	for (;;) {
		is_appointment = is_event = is_recursive = 0;
		line++;
		rpt_init(&rpt);
		sh = smin = eh = emin = 0;
		em = ed = ey = 0;

		c = getc(fp);
		if (c == EOF)
			break;
		ungetc(c, fp);

		if (fscanf(fp, "%d / %d / %d ", &sm, &sd, &sy) != 3)
			io_load_error(path_apts, line,
				      "syntax error in the item date");

		c = getc(fp);
		if (c == '@')
			is_appointment = 1;
		else if (c == '[')
			is_event = 1;
		else
			io_load_error(path_apts, line,
				      "no event nor appointment found");

		if (is_appointment) {
			if (fscanf(fp, " %d : %d -> %d / %d / %d @ %d : %d ",
				   &sh, &smin, &em, &ed, &ey, &eh,
				   &emin) != 7)
				io_load_error(path_apts, line,
					      "syntax error in item time or duration");
		} else {
			if (fscanf(fp, " %d ", &id) != 1 || getc(fp) != ']')
				io_load_error(path_apts, line,
					      "syntax error in item identifier");
			while ((c = getc(fp)) == ' ')
				;
			ungetc(c, fp);
		}

		c = getc(fp);
		if (c == '{') {
			int freq;
			is_recursive = 1;
			if (fscanf(fp, " %d%c ", &freq, &type) != 2)
				io_load_error(path_apts, line,
					      "syntax error in item repetition");
			rpt.freq = freq;
			rpt.type = recur_char2def(type);
			c = getc(fp);
			if (c == '-' && getc(fp) == '>') {
				if (fscanf(fp, " %d / %d / %d ", &um, &ud,
					   &uy) != 3)
					io_load_error(path_apts, line,
						      "syntax error in until date");
				if (!check_date(uy, um, ud))
					io_load_error(path_apts, line,
						      "until date error");
				rpt.until = date2sec(uy, um, ud, 0, 0);
				c = getc(fp);
			} else {
				rpt.until = 0;
			}
			read_list(fp, &c, 'd', &rpt.bymonthday, 1640,
				  "syntax error in bymonthday", NULL, &rpt, 0,
				  NULL);
			read_list(fp, &c, 'w', &rpt.bywday, 1659,
				  "syntax error in bywday", check_wday_scan,
				  &rpt, 1661, "illegal BYDAY value");
			read_list(fp, &c, 'm', &rpt.bymonth, 1678,
				  "syntax error in bymonth", check_month_scan,
				  &rpt, 1679, "illegal bymonth value");
			if (rpt.type == RECUR_WEEKLY && rpt.bymonthday.n)
				io_load_error(path_apts, line,
					      "BYMONTHDAY illegal with WEEKLY");
			if (c == '!') {
				ungetc(c, fp);
				exc_scan(&rpt.exc, fp);
				c = getc(fp);
			}
			if (c != '}')
				io_load_error(path_apts, line,
					      "missing end of recurrence");
			while ((c = getc(fp)) == ' ')
				;
		}

		if (c == '>') {
			note_read(note, fp);
			c = getc(fp);
			notep = note;
		} else {
			notep = NULL;
		}

		if (is_appointment) {
			if (c == '!')
				state |= APOINT_NOTIFY;
			else if (c == '|')
				state = 0;
			else
				io_load_error(path_apts, line,
					      "syntax error in item state");
		} else {
			ungetc(c, fp);
		}

		if (is_appointment) {
			time_t tstart, tend;
			if (!check_date(sy, sm, sd) || !check_date(ey, em, ed) ||
			    !check_time(sh, smin) || !check_time(eh, emin))
				io_load_error(path_apts, line,
					      "illegal date in appointment");
			read_desc(fp, buf, sizeof(buf), path_apts, line);
			tstart = date2sec(sy, sm, sd, sh, smin);
			tend = date2sec(ey, em, ed, eh, emin);
			if (tstart == -1 || tend == -1 || tstart > tend)
				io_load_error(path_apts, line,
					      "date error in appointment");
			if (is_recursive) {
				struct recur_apoint *ra;
				if (!recur_candidate(tstart, &rpt, tstart)) {
					char d[64], msg[128];
					format_date_numeric(d, sizeof(d), tstart,
							    conf.input_datefmt);
					snprintf(msg, sizeof(msg),
						 "recurrence error: not on start day (%s)",
						 d);
					io_load_error(path_apts, line, msg);
				}
				ra = recur_apoint_new(buf, notep, tstart,
						      tend - tstart, state,
						      &rpt);
				if (filter_recur_apoint(filter, ra))
					plist_add_sorted(&ralist, ra,
							 recur_apoint_cmp);
			} else {
				struct apoint *a;
				a = apoint_new(buf, notep, tstart,
					       tend - tstart, state);
				if (filter_apoint(filter, a))
					plist_add_sorted(&alist, a, apoint_cmp);
			}
		} else {
			time_t tday;
			if (!check_date(sy, sm, sd))
				io_load_error(path_apts, line,
					      is_recursive ?
					      "illegel date in event" :
					      "illegal date in event");
			read_desc(fp, buf, sizeof(buf), path_apts, line);
			tday = date2sec(sy, sm, sd, 0, 0);
			if (tday == -1)
				io_load_error(path_apts, line,
					      "date error in event");
			if (is_recursive) {
				struct recur_event *re;
				if (!recur_candidate(tday, &rpt, tday)) {
					char d[64], msg[128];
					format_date_numeric(d, sizeof(d), tday,
							    conf.input_datefmt);
					snprintf(msg, sizeof(msg),
						 "recurrence error: not on start day (%s)",
						 d);
					io_load_error(path_apts, line, msg);
				}
				re = recur_event_new(buf, notep, tday, id, &rpt);
				if (filter_recur_event(filter, re))
					plist_add_sorted(&relist, re,
							 recur_event_cmp);
			} else {
				struct event *e;
				e = event_new(buf, notep, tday, id);
				if (filter_event(filter, e))
					plist_add_sorted(&elist, e, event_cmp);
			}
		}
		rpt_free(&rpt);
	}
	fclose(fp);
}

void io_load_todo(struct item_filter *filter)
{
	FILE *fp;
	int c, id, completed;
	char buf[16384], *nl;
	char note[MAX_NOTESIZ + 1], *notep;
	unsigned line = 0;

	fp = fopen(path_todo, "r");
	if (!fp)
		die_at("io.c", 755, "failed to open todo file");

	for (;;) {
		line++;
		c = getc(fp);
		if (c == EOF)
			break;
		if (c == '[') {
			if (fscanf(fp, "%d", &id) != 1)
				break;
			completed = 0;
			if (id < 0) {
				completed = 1;
				id = -id;
			} else if (id == 0) {
				/* check for "-0" */
			}
			c = getc(fp);
			if (c != ']')
				die_at("io.c", 777, "%s:%u: syntax error in item priority",
				       path_todo, line);
			c = getc(fp);
			if (c == '>') {
				note_read(note, fp);
				notep = note;
			} else {
				notep = NULL;
				ungetc(c, fp);
				c = getc(fp);
				if (c != ' ')
					ungetc(c, fp);
			}
		} else {
			id = 9;
			completed = 0;
			notep = NULL;
			ungetc(c, fp);
		}
		if (!fgets(buf, sizeof(buf), fp))
			break;
		nl = strchr(buf, '\n');
		if (nl)
			*nl = '\0';
		{
			struct todo *t = todo_new(buf, id, completed, notep);
			if (filter_todo(filter, t))
				plist_add_sorted(&tlist, t, todo_cmp);
		}
	}
	fclose(fp);
}

int io_save_apts(const char *path)
{
	FILE *fp;
	int i;

	if (read_only)
		return 1;
	fp = fopen(path, "w");
	if (!fp)
		return 0;
	for (i = 0; i < relist.n; i++)
		recur_event_write(relist.v[i], fp);
	for (i = 0; i < ralist.n; i++)
		recur_apoint_write(ralist.v[i], fp);
	for (i = 0; i < alist.n; i++)
		apoint_write(alist.v[i], fp);
	for (i = 0; i < elist.n; i++)
		event_write(elist.v[i], fp);
	fclose(fp);
	return 1;
}

int io_save_todo(const char *path)
{
	FILE *fp;
	int i;

	if (read_only)
		return 1;
	fp = fopen(path, "w");
	if (!fp)
		return 0;
	for (i = 0; i < tlist.n; i++)
		todo_write(tlist.v[i], fp);
	fclose(fp);
	return 1;
}

/* Run a hook script if it exists and is executable. */
void run_hook(const char *name)
{
	char *path;
	pid_t pid;
	int status;

	path = xmalloc(strlen(path_hooks) + strlen(name) + 2);
	sprintf(path, "%s/%s", path_hooks, name);
	if (access(path, X_OK) != 0) {
		free(path);
		return;
	}
	fflush(stdout);
	fflush(stderr);
	pid = fork();
	if (pid == 0) {
		int fd = open("/dev/null", O_RDWR);
		if (fd >= 0) {
			dup2(fd, 0);
			dup2(fd, 1);
			dup2(fd, 2);
			if (fd > 2)
				close(fd);
		}
		execl(path, path, (char *)NULL);
		_exit(127);
	} else if (pid > 0) {
		while (waitpid(pid, &status, 0) < 0 && errno == EINTR)
			;
	}
	free(path);
}

/*
 * Notes.
 */
char *generate_note(const char *str)
{
	char hex[41];
	char *path;
	FILE *fp;

	sha1_digest(str, strlen(str), hex);
	path = mkpath(path_notes, hex);
	if (!read_only && !io_file_exists(path)) {
		fp = fopen(path, "w");
		if (fp) {
			fputs(str, fp);
			fclose(fp);
		}
	}
	free(path);
	return xstrdup(hex);
}

static int note_used(const char *name)
{
	int i;
#define CHECK(list, type)                                              \
	for (i = 0; i < (list).n; i++) {                               \
		type *x = (list).v[i];                                 \
		if (x->note && !strcmp(x->note, name))                 \
			return 1;                                      \
	}
	CHECK(alist, struct apoint);
	CHECK(elist, struct event);
	CHECK(ralist, struct recur_apoint);
	CHECK(relist, struct recur_event);
	CHECK(tlist, struct todo);
#undef CHECK
	return 0;
}

void note_gc(void)
{
	DIR *dir;
	struct dirent *dp;

	dir = opendir(path_notes);
	if (!dir)
		return;
	while ((dp = readdir(dir)) != NULL) {
		const char *n = dp->d_name;
		int i, ok = 1;
		char *path;
		if (strlen(n) != 40)
			continue;
		for (i = 0; i < 40; i++) {
			if (!((n[i] >= '0' && n[i] <= '9') ||
			      (n[i] >= 'a' && n[i] <= 'f'))) {
				ok = 0;
				break;
			}
		}
		if (!ok || note_used(n))
			continue;
		path = mkpath(path_notes, n);
		unlink(path);
		free(path);
	}
	closedir(dir);
}

/*
 * Lock / pid files.
 */
unsigned io_get_pid(const char *file)
{
	FILE *fp;
	unsigned pid;

	if (!file)
		return 0;
	if ((fp = fopen(file, "r")) == NULL)
		return 0;
	if (fscanf(fp, "%u", &pid) != 1)
		pid = 0;
	fclose(fp);
	return pid;
}

void io_set_pid(const char *file)
{
	FILE *fp;
	if (read_only)
		return;
	fp = fopen(file, "w");
	if (!fp)
		return;
	fprintf(fp, "%d\n", (int)getpid());
	fclose(fp);
}
