	if (!strcmp(key, "appearance.notifybar"))
		return parse_bool(&conf.notify_bar, val);
	if (!strcmp(key, "appearance.sidebarwidth")) {
		conf.sidebar_width = atoi(val);
		return 1;
	}
	if (!strcmp(key, "appearance.theme"))
		return parse_theme(val);
	if (!strcmp(key, "appearance.todoview")) {
		if (!strcmp(val, "show-completed"))
