	if (!strcmp(key, "appearance.dayseparator"))
		return parse_bool(&conf.day_separator, val);
	if (!strcmp(key, "appearance.emptyline"))
		return parse_bool(&conf.empty_appt_line, val);
	if (!strcmp(key, "appearance.emptyday"))
