static int parse_bool(int *dest, const char *val)
{
	if (!strcmp(val, "yes"))
		*dest = 1;
	else if (!strcmp(val, "no"))
		*dest = 0;
	else
		return 0;
	return 1;
}

static int parse_int(int *dest, const char *val)
{
	const char *p = val;
	if (*p == '+' || *p == '-')
		p++;
	for (; *p; p++)
		if (!isdigit((unsigned char)*p))
			return 0;
	*dest = atoi(val);
	return 1;
}

static int parse_unsigned(int *dest, const char *val)
{
	int v;
	if (!parse_int(&v, val) || v < 0)
		return 0;
	*dest = v;
	return 1;
}

static int parse_str(char *dest, const char *val)
{
	if (!*val)
		return 1;
	snprintf(dest, BUFSIZ_, "%s", val);
	return 1;
}

static int parse_theme(const char *val)
{
	static const char *colors[] = { "default", "black", "red", "green",
		"yellow", "blue", "magenta", "cyan", "white", NULL };
	char fg[64], bg[64], extra;
	int i, okf = 0, okb = 0;

	if (!strcmp(val, "0") || !strcmp(val, "none") ||
	    !strcmp(val, "default")) {
		snprintf(conf.theme, BUFSIZ_, "%s", val);
		return 1;
	}
	if (sscanf(val, "%63s on %63s%c", fg, bg, &extra) != 2)
		return 0;
	for (i = 0; colors[i]; i++) {
		if (!strcmp(fg, colors[i]))
			okf = 1;
		if (!strcmp(bg, colors[i]))
			okb = 1;
	}
	if (!okf || !okb)
		return 0;
	snprintf(conf.theme, BUFSIZ_, "%s", val);
	return 1;
}

