# generate a C string for the help text
s = open('help.txt').read()
usage_end = s.index('\n\n') + 1
usage = s[:usage_end]
rest = s[usage_end:]
def cstr(t):
    out = []
    for line in t.split('\n'):
        pass
    lines = t.split('\n')
    res = []
    for i, line in enumerate(lines):
        if i == len(lines) - 1:
            if line == '':
                break
            res.append('"' + line.replace('\\', '\\\\').replace('"', '\\"') + '"')
        else:
            res.append('"' + line.replace('\\', '\\\\').replace('"', '\\"') + '\\n"')
    return '\n\t'.join(res)
with open('help.h', 'w') as f:
    f.write('static const char usage_text[] =\n\t' + cstr(usage) + ';\n\n')
