/* Parse a date argument (numeric or one of the short forms). */
static int parse_datearg(const char *str, time_t *out)
{
	int y, m, d, i;
	static const char *wdays[] = { "sunday", "monday", "tuesday",
		"wednesday", "thursday", "friday", "saturday" };
	time_t today = get_today();
	struct tm lt;

	if (parse_date(str, conf.input_datefmt, &y, &m, &d)) {
		*out = date2sec(y, m, d, 0, 0);
		return 1;
	}
	if (!strcasecmp(str, "today") || !strcasecmp(str, "now")) {
		*out = today;
		return 1;
	}
	if (!strcasecmp(str, "tomorrow")) {
		*out = date_sec_change(today, 0, 1);
		return 1;
	}
	if (!strcasecmp(str, "yesterday")) {
		*out = date_sec_change(today, 0, -1);
		return 1;
	}
	localtime_r(&today, &lt);
	for (i = 0; i < 7; i++) {
		if (!strcasecmp(str, wdays[i]) ||
		    (strlen(str) == 3 && !strncasecmp(str, wdays[i], 3))) {
			int n = i - lt.tm_wday;
			if (n <= 0)
				n = 7;
			*out = date_sec_change(today, 0, n);
			return 1;
		}
	}
	return 0;
}

/*
 * Parse a date argument optionally followed by a time ("date hh:mm").
 * *has_time is set if a time was given.
 */
static int parse_datetimearg(const char *str, time_t *out, int *has_time)
{
	char *s = xstrdup(str), *sp;
	int h, m, ret = 0;
	time_t t;

	*has_time = 0;
	sp = strchr(s, ' ');
	if (sp) {
		*sp = '\0';
		if (!parse_time(sp + 1, &h, &m))
			goto out;
		if (!parse_datearg(s, &t))
			goto out;
		*out = update_time_in_date(t, h, m);
		*has_time = 1;
		ret = 1;
	} else {
		ret = parse_datearg(s, out);
	}
out:
	free(s);
	return ret;
}

static int is_number_arg(const char *s)
{
	if (*s == '-')
		s++;
	for (; *s; s++)
		if (*s < '0' || *s > '9')
			return 0;
	return 1;
}

static int parse_type_mask(const char *str)
{
	char *buf = xstrdup(str), *p, *tok, *save = NULL;
	int mask = 0;

	for (p = buf; (tok = strtok_r(p, ",", &save)) != NULL; p = NULL) {
		if (!strcmp(tok, "event"))
			mask |= TYPE_EVNT;
		else if (!strcmp(tok, "apt"))
			mask |= TYPE_APPT;
		else if (!strcmp(tok, "recur-event"))
			mask |= TYPE_RECUR_EVNT;
		else if (!strcmp(tok, "recur-apt"))
			mask |= TYPE_RECUR_APPT;
		else if (!strcmp(tok, "recur"))
			mask |= TYPE_MASK_RECUR;
		else if (!strcmp(tok, "cal"))
			mask |= TYPE_MASK_CAL;
		else if (!strcmp(tok, "todo"))
			mask |= TYPE_TODO;
		else {
			mask = 0;
			break;
		}
	}
	free(buf);
	return mask;
}

/*
 * Data loading helpers.
 */
static void load_data(struct item_filter *filter)
{
	run_hook("pre-load");
	io_load_app(filter);
	io_load_todo(filter);
	run_hook("post-load");
}

static void print_date_line(time_t date, const char *fmt)
{
	char buf[BUFSIZ_ * 4];
	struct tm lt;

	localtime_r(&date, &lt);
	buf[0] = '\0';
	strftime(buf, sizeof(buf), fmt, &lt);
	fputs(buf, stdout);
	fputs(":\n", stdout);
}

static int todo_arg(const char *fmt, int *limit, struct item_filter *filter)
{
	int i, title = 1;

	for (i = 0; i < tlist.n; i++) {
		if (*limit == 0)
			break;
		if (title) {
			fputs(filter->completed ? "completed tasks:\n" :
			      "to do:\n", stdout);
			title = 0;
		}
		print_todo(fmt, tlist.v[i]);
		if (*limit > 0)
			(*limit)--;
	}
	return !title;
}

static void day_write_stdout(time_t date, const char *fmt_apt,
			     const char *fmt_rapt, const char *fmt_ev,
			     const char *fmt_rev, int *limit)
{
	int i, n = day_item_count();

	for (i = 0; i < n; i++) {
		struct day_item *it = day_get_item(i);
		if (*limit == 0)
			break;
		switch (it->type) {
		case DI_APPT:
			print_apoint(fmt_apt, date, it->item);
			break;
		case DI_EVNT:
			print_event(fmt_ev, date, it->item);
			break;
		case DI_RECUR_APPT:
			print_recur_apoint(fmt_rapt, date, it->start, it->item);
			break;
		case DI_RECUR_EVNT:
			print_recur_event(fmt_rev, date, it->item);
			break;
		}
		if (*limit > 0)
			(*limit)--;
	}
}

static void date_arg_from_to(time_t from, time_t to, int add_line,
			     const char *datefmt, const char *fmt_apt,
			     const char *fmt_rapt, const char *fmt_ev,
			     const char *fmt_rev, int *limit,
			     int include_rapts)
{
	time_t date;

	for (date = from; date <= to; date = date_sec_change(date, 0, 1)) {
		day_store_items(date, include_rapts);
		if (day_item_count() == 0)
			continue;
		if (add_line)
			fputs("\n", stdout);
		print_date_line(date, datefmt);
		day_write_stdout(date, fmt_apt, fmt_rapt, fmt_ev, fmt_rev,
				 limit);
		add_line = 1;
	}
}

static void grep_data(const char *fmt_ev, const char *fmt_rev,
		      const char *fmt_apt, const char *fmt_rapt,
		      const char *fmt_todo)
{
	int i;

	for (i = 0; i < tlist.n; i++)
		print_todo(fmt_todo, tlist.v[i]);
	for (i = 0; i < relist.n; i++) {
		struct recur_event *r = relist.v[i];
		print_recur_event(fmt_rev, r->day, r);
	}
	for (i = 0; i < ralist.n; i++) {
		struct recur_apoint *r = ralist.v[i];
		print_recur_apoint(fmt_rapt,
				   update_time_in_date(r->start, 0, 0),
				   r->start, r);
	}
	for (i = 0; i < alist.n; i++) {
		struct apoint *a = alist.v[i];
		print_apoint(fmt_apt, update_time_in_date(a->start, 0, 0), a);
	}
	for (i = 0; i < elist.n; i++) {
		struct event *e = elist.v[i];
		print_event(fmt_ev, e->day, e);
	}
}

/* -n: print the next appointment within 24 hours. */
static void next_arg(void)
{
	time_t now = time(NULL);
	time_t cur = now - (now % 60);
	time_t best = now + DAYINSEC;
	const char *txt = NULL;
	int got = 0, i;
	time_t today = get_today();

	(void)cur;
	for (i = 0; i < alist.n; i++) {
		struct apoint *a = alist.v[i];
		if (a->start > now && a->start < best) {
			best = a->start;
			txt = a->mesg;
			got = 1;
		}
	}
	for (i = 0; i < ralist.n; i++) {
		struct recur_apoint *r = ralist.v[i];
		time_t day, occ;
		int k;
		for (k = 0, day = today; k < 2;
		     k++, day = date_sec_change(day, 0, 1)) {
			if (recur_apoint_find_occurrence(r, day, &occ) &&
			    occ > now && occ < best) {
				best = occ;
				txt = r->mesg;
				got = 1;
			}
		}
	}
	if (got) {
		long left = (long)(best - (now - now % 60));
		int hours = (int)(left / HOURINSEC);
		int mins = (int)((left - hours * HOURINSEC) / MININSEC);
		fputs("next appointment:\n", stdout);
		printf("   [%02d:%02d] %s\n", hours, mins, txt);
	}
}

static void status_arg(void)
{
	unsigned cpid = io_get_pid(path_cpid);
	unsigned dpid = io_get_pid(path_dpid);

	if (cpid && dpid) {
		die_at("args.c", 181,
		       "Error: both calcurse (pid: %u) and its daemon (pid: %u)\n"
		       "seem to be running at the same time!\n"
		       "Please check manually and restart calcurse.\n",
		       cpid, dpid);
	} else if (cpid) {
		printf("calcurse is running (pid %u)\n", cpid);
	} else if (dpid) {
		printf("calcurse is running in background (pid %u)\n", dpid);
	} else {
		puts("calcurse is not running");
	}
}

/* Background notification daemon. */
static volatile sig_atomic_t daemon_stop = 0;

static void daemon_sigterm(int sig)
{
	(void)sig;
	daemon_stop = 1;
}

static void daemon_notify_check(void)
{
	time_t now = time(NULL);
	int i;
	time_t today = get_today();

	plist_clear(&alist);
	plist_clear(&ralist);
	plist_clear(&elist);
	plist_clear(&relist);
	plist_clear(&tlist);
	if (!io_file_exists(path_apts))
		return;
	io_load_app(NULL);
	for (i = 0; i < alist.n; i++) {
		struct apoint *a = alist.v[i];
		long left = (long)(a->start - now);
		int flagged = a->state & APOINT_NOTIFY;
		int want = conf.notify_all == 1 ||
			   (conf.notify_all == 0 && flagged) ||
			   (conf.notify_all == 2 && !flagged);
		if (want && left > 0 && left <= conf.notify_warning &&
		    left > conf.notify_warning - 60) {
			if (fork() == 0) {
				execl("/bin/sh", "sh", "-c", conf.notify_cmd,
				      (char *)NULL);
				_exit(127);
			}
		}
	}
	(void)today;
}

static void start_daemon(void)
{
	unsigned dpid = io_get_pid(path_dpid);
	pid_t pid;

	if (dpid)
		kill((pid_t)dpid, SIGTERM);

	fflush(stdout);
	pid = fork();
	if (pid < 0)
		return;
	if (pid > 0)
		return;
	setsid();
	pid = fork();
	if (pid != 0)
		_exit(0);
	{
		int fd = open("/dev/null", O_RDWR);
		if (fd >= 0) {
			dup2(fd, 0);
			dup2(fd, 1);
			dup2(fd, 2);
			if (fd > 2)
				close(fd);
		}
	}
	signal(SIGTERM, daemon_sigterm);
	signal(SIGCHLD, SIG_IGN);
	io_set_pid(path_dpid);
	while (!daemon_stop) {
		daemon_notify_check();
		{
			time_t now = time(NULL);
			unsigned s = (unsigned)(60 - now % 60);
			while (s > 0 && !daemon_stop)
				s = sleep(s);
		}
	}
	unlink(path_dpid);
	_exit(0);
}

int main(int argc, char **argv)
{
	int ch;
	const char *cfile = NULL, *datadir = NULL, *confdir = NULL;
	struct item_filter filter;
	int query = 0, next = 0, grep = 0, purge = 0, filter_cmd = 0;
	int export = 0, import = 0, gc = 0, status = 0, daemon_opt = 0;
	int xfmt_pcal = 0, export_uid = 0, dump_imported = 0;
	int filter_opt = 0, format_opt = 0, range_opt = 0;
	int non_interactive = 0;
	const char *ifile = NULL;
	int limit = -1;
	int range = 0, range_set = 0;
	time_t from = -1, to = -1;
	const char *fmt_apt = NULL, *fmt_rapt = NULL, *fmt_ev = NULL,
		   *fmt_rev = NULL, *fmt_todo = NULL;
	char output_datefmt[BUFSIZ_];
	int output_datefmt_set = 0;
	int has_time;
	time_t t;
	char *dup, *comma;
	time_t a, b;

	setlocale(LC_ALL, "");
	config_init();

	memset(&filter, 0, sizeof(filter));
	filter.type_mask = 0;
	filter.start_from = filter.start_to = -1;
	filter.end_from = filter.end_to = -1;

	/* First pass: directories and calendar file. */
	while ((ch = getopt_long(argc, argv, optstr, longopts, NULL)) != -1) {
		switch (ch) {
		case 'c':
			cfile = optarg;
			break;
		case 'C':
			confdir = optarg;
			break;
		case 'D':
			datadir = optarg;
			break;
		case '?':
			usage_try();
			break;
		default:
			break;
		}
	}

	io_init(cfile, datadir, confdir);
	config_load();

	/* Second pass. */
	optind = 0;
	opterr = 0;
	while ((ch = getopt_long(argc, argv, optstr, longopts, NULL)) != -1) {
		switch (ch) {
		case 'a':
			filter.type_mask |= TYPE_MASK_CAL;
			query = 1;
			break;
		case 'c':
		case 'C':
		case 'D':
			break;
		case 'd':
			if (is_number_arg(optarg)) {
				range = atoi(optarg);
				if (range == 0)
					die_at("args.c", 546, "invalid range: %s",
					       optarg);
				range_set = 1;
			} else {
				if (!parse_datearg(optarg, &from))
					die_at("args.c", 550, "invalid date: %s",
					       optarg);
				to = from;
			}
			filter.type_mask |= TYPE_MASK_CAL;
			query = 1;
			break;
		case 'F':
			filter_cmd = 1;
			break;
		case 'g':
			gc = 1;
			break;
		case 'G':
			grep = 1;
			break;
		case 'h':
			help();
			break;
		case 'i':
			import = 1;
			ifile = optarg;
			break;
		case 'l':
			limit = atoi(optarg);
			break;
		case 'n':
			next = 1;
			break;
		case 'N':
			break;
		case 'P':
			purge = 1;
			break;
		case 'q':
			quiet = 1;
			break;
		case 'Q':
			query = 1;
			break;
		case 'r':
			if (optarg) {
				range = atoi(optarg);
				if (range == 0)
					die_at("args.c", 590, "invalid range: %s",
					       optarg);
			} else {
				range = 1;
			}
			range_set = 1;
			filter.type_mask |= TYPE_MASK_CAL;
			query = 1;
			break;
		case 's':
			if (optarg) {
				if (!parse_datearg(optarg, &from))
					die_at("args.c", 598, "invalid date: %s",
					       optarg);
			} else {
				from = get_today();
			}
			filter.type_mask |= TYPE_MASK_CAL;
			query = 1;
			break;
		case 't':
			filter.type_mask |= TYPE_TODO;
			if (optarg) {
				const char *p;
				int pr;
				for (p = optarg; *p; p++)
					if (*p < '0' || *p > '9')
						die_at("args.c", 605,
						       "invalid priority: %s",
						       optarg);
				pr = atoi(optarg);
				if (pr < 0 || pr > 9)
					die_at("args.c", 612,
					       "invalid priority: %s", optarg);
				if (pr == 0) {
					filter.completed = 1;
				} else {
					filter.priority = pr;
					filter.uncompleted = 1;
				}
			} else {
				filter.uncompleted = 1;
			}
			query = 1;
			break;
		case 'v':
			version();
			break;
		case 'x':
			export = 1;
			if (optarg) {
				if (!strcmp(optarg, "ical"))
					xfmt_pcal = 0;
				else if (!strcmp(optarg, "pcal"))
					xfmt_pcal = 1;
				else
					die_at("args.c", 631,
					       "invalid export format: %s",
					       optarg);
			} else {
				xfmt_pcal = 0;
			}
			break;
		case OPT_FILTER_INVERT:
			filter.invert = !filter.invert;
			filter_opt = 1;
			break;
		case OPT_FILTER_TYPE:
			filter.type_mask = parse_type_mask(optarg);
			if (filter.type_mask == 0)
				die_at("args.c", 647, "invalid filter mask");
			filter_opt = 1;
			break;
		case OPT_FILTER_HASH:
			filter.hash = xstrdup(optarg);
			filter_opt = 1;
			break;
		case 'S':
		case OPT_FILTER_PATTERN:
			if (filter.regex) {
				regfree(filter.regex);
			} else {
				filter.regex = xmalloc(sizeof(regex_t));
			}
			if (regcomp(filter.regex, optarg, REG_EXTENDED))
				die_at("args.c", 660,
				       "could not compile regular expression: %s",
				       optarg);
			filter_opt = 1;
			break;
		case OPT_FILTER_START_FROM:
			if (filter.start_from >= 0)
				die_at("args.c", 670,
				       "filter criterion already in use: %s",
				       "--filter-start-from");
			if (!parse_datetimearg(optarg, &t, &has_time))
				die_at("args.c", 673, "invalid date: %s", optarg);
			filter.start_from = t;
			filter_opt = 1;
			break;
		case OPT_FILTER_START_TO:
			if (filter.start_to >= 0)
				die_at("args.c", 679,
				       "filter criterion already in use: %s",
				       "--filter-start-to");
			if (!parse_datetimearg(optarg, &t, &has_time))
				die_at("args.c", 682, "invalid date: %s", optarg);
			filter.start_to = has_time ? t : t + DAYINSEC - 1;
			filter_opt = 1;
			break;
		case OPT_FILTER_START_AFTER:
			if (filter.start_from >= 0)
				die_at("args.c", 690,
				       "filter criterion already in use: %s",
				       "--filter-start-after");
			if (!parse_datetimearg(optarg, &t, &has_time))
				die_at("args.c", 693, "invalid date: %s", optarg);
			filter.start_from = (has_time ? t : t + DAYINSEC - 1) + 1;
			filter_opt = 1;
			break;
		case OPT_FILTER_START_BEFORE:
			if (filter.start_to >= 0)
				die_at("args.c", 703,
				       "filter criterion already in use: %s",
				       "--filter-start-before");
			if (!parse_datetimearg(optarg, &t, &has_time))
				die_at("args.c", 706, "invalid date: %s", optarg);
			filter.start_to = t - 1;
			filter_opt = 1;
			break;
		case OPT_FILTER_START_RANGE:
			if (filter.start_from >= 0)
				die_at("args.c", 713,
				       "filter criterion already in use: %s",
				       "--filter-start-range");
			if (filter.start_to >= 0)
				die_at("args.c", 715,
				       "filter criterion already in use: %s",
				       "--filter-start-range");
			dup = xstrdup(optarg);
			comma = strchr(dup, ',');
			if (!comma || strchr(comma + 1, ','))
				die_at("args.c", 719, "invalid date range: %s",
				       optarg);
			*comma = '\0';
			if (!parse_datetimearg(dup, &a, &has_time))
				die_at("args.c", 719, "invalid date range: %s",
				       optarg);
			filter.start_from = a;
			if (!parse_datetimearg(comma + 1, &b, &has_time))
				die_at("args.c", 719, "invalid date range: %s",
				       optarg);
			filter.start_to = has_time ? b : b + DAYINSEC - 1;
			free(dup);
			filter_opt = 1;
			break;
		case OPT_FILTER_END_FROM:
			if (filter.end_from >= 0)
				die_at("args.c", 726,
				       "filter criterion already in use: %s",
				       "--filter-end-from");
			if (!parse_datetimearg(optarg, &t, &has_time))
				die_at("args.c", 729, "invalid date: %s", optarg);
			filter.end_from = t;
			filter_opt = 1;
			break;
		case OPT_FILTER_END_TO:
			if (filter.end_to >= 0)
				die_at("args.c", 735,
				       "filter criterion already in use: %s",
				       "--filter-end-to");
			if (!parse_datetimearg(optarg, &t, &has_time))
				die_at("args.c", 738, "invalid date: %s", optarg);
			filter.end_to = has_time ? t : t + DAYINSEC - 1;
			filter_opt = 1;
			break;
		case OPT_FILTER_END_AFTER:
			if (filter.end_from >= 0)
				die_at("args.c", 746,
				       "filter criterion already in use: %s",
				       "--filter-end-after");
			if (!parse_datetimearg(optarg, &t, &has_time))
				die_at("args.c", 749, "invalid date: %s", optarg);
			filter.end_from = (has_time ? t : t + DAYINSEC - 1) + 1;
			filter_opt = 1;
			break;
		case OPT_FILTER_END_BEFORE:
			if (filter.end_to >= 0)
				die_at("args.c", 759,
				       "filter criterion already in use: %s",
				       "--filter-end-before");
			if (!parse_datetimearg(optarg, &t, &has_time))
				die_at("args.c", 762, "invalid date: %s", optarg);
			filter.end_to = t - 1;
			filter_opt = 1;
			break;
		case OPT_FILTER_END_RANGE:
			if (filter.end_from >= 0)
				die_at("args.c", 769,
				       "filter criterion already in use: %s",
				       "--filter-end-range");
			if (filter.end_to >= 0)
				die_at("args.c", 771,
				       "filter criterion already in use: %s",
				       "--filter-end-range");
			dup = xstrdup(optarg);
			comma = strchr(dup, ',');
			if (!comma || strchr(comma + 1, ','))
				die_at("args.c", 775, "invalid date range: %s",
				       optarg);
			*comma = '\0';
			if (!parse_datetimearg(dup, &a, &has_time))
				die_at("args.c", 775, "invalid date range: %s",
				       optarg);
			filter.end_from = a;
			if (!parse_datetimearg(comma + 1, &b, &has_time))
				die_at("args.c", 775, "invalid date range: %s",
				       optarg);
			filter.end_to = has_time ? b : b + DAYINSEC - 1;
			free(dup);
			filter_opt = 1;
			break;
		case OPT_FILTER_PRIORITY:
			if (strlen(optarg) != 1 || optarg[0] < '1' ||
			    optarg[0] > '9')
				die_at("args.c", 783, "invalid priority: %s",
				       optarg);
			filter.priority = optarg[0] - '0';
			filter_opt = 1;
			break;
		case OPT_FILTER_COMPLETED:
			filter.completed = 1;
			filter_opt = 1;
			break;
		case OPT_FILTER_UNCOMPLETED:
			filter.uncompleted = 1;
			filter_opt = 1;
			break;
		case OPT_FROM:
			if (!parse_datearg(optarg, &from))
				die_at("args.c", 797, "invalid date: %s", optarg);
			range_opt = 1;
			break;
		case OPT_TO:
			if (!parse_datearg(optarg, &to))
				die_at("args.c", 803, "invalid date: %s", optarg);
			range_opt = 1;
			break;
		case OPT_DAYS:
			range = atoi(optarg);
			if (range == 0)
				die_at("args.c", 809, "invalid range: %s",
				       optarg);
			range_set = 1;
			range_opt = 1;
			break;
		case OPT_FMT_APT:
			fmt_apt = optarg;
			format_opt = 1;
			break;
		case OPT_FMT_RAPT:
			fmt_rapt = optarg;
			format_opt = 1;
			break;
		case OPT_FMT_EV:
			fmt_ev = optarg;
			format_opt = 1;
			break;
		case OPT_FMT_REV:
			fmt_rev = optarg;
			format_opt = 1;
			break;
		case OPT_FMT_TODO:
			fmt_todo = optarg;
			format_opt = 1;
			break;
		case OPT_EXPORT_UID:
			export_uid = 1;
			break;
		case OPT_DUMP_IMPORTED:
			dump_imported = 1;
			break;
		case OPT_INPUT_DATEFMT: {
			int v = atoi(optarg);
			if (v < 1 || v > 4)
				die_at("args.c", 852,
				       "invalid input date format: %s", optarg);
			conf.input_datefmt = v;
			non_interactive = 1;
			break;
		}
		case OPT_OUTPUT_DATEFMT:
			if (!optarg[0])
				die_at("args.c", 859,
				       "invalid output date format: %s", optarg);
			snprintf(output_datefmt, sizeof(output_datefmt), "%s",
				 optarg);
			output_datefmt_set = 1;
			non_interactive = 1;
			break;
		case OPT_STATUS:
			status = 1;
			break;
		case OPT_DAEMON:
			daemon_opt = 1;
			break;
		case OPT_READ_ONLY:
			read_only = 1;
			break;
		default:
			break;
		}
	}

	{
		int ncmd = 0;
		int grp = grep || purge || filter_cmd;
		ncmd = query + next + grp + export + import + gc + status +
		       daemon_opt;
		if (optind < argc || ncmd > 1)
			die_at("args.c", 880, "invalid argument combination");
		if (filter_opt && !(query || grp || export))
			die_at("args.c", 880, "invalid argument combination");
		if (format_opt && !(query || grp || (import && dump_imported)))
			die_at("args.c", 880, "invalid argument combination");
		if (range_opt && !query)
			die_at("args.c", 880, "invalid argument combination");
		if (ncmd)
			non_interactive = 1;
	}

	if (query) {
		if (to >= 0 && range_set)
			die_at("args.c", 882,
			       "cannot specify a range and an end date");
	}

	if (!non_interactive)
		return ui_main();

	if (!output_datefmt_set)
		snprintf(output_datefmt, sizeof(output_datefmt), "%s",
			 conf.output_datefmt);

	/* Directories. */
	io_check_dir(path_ddir);
	io_check_dir(path_cdir);
	io_check_dir(path_notes);
	io_check_dir(path_hooks);

	if (status) {
		status_arg();
		return EXIT_SUCCESS;
	}

	if (daemon_opt) {
		unsigned cpid = io_get_pid(path_cpid);
		if (cpid)
			die_at("args.c", 845, "calcurse is running (pid = %u)",
			       cpid);
		io_check_file(path_apts);
		io_check_file(path_todo);
		start_daemon();
		return EXIT_SUCCESS;
	}

	if (query) {
		time_t today = get_today();
		int add_line = 0;

		if (from < 0)
			from = today;
		if (range_set) {
			if (range > 0) {
				to = date_sec_change(from, 0, range - 1);
			} else {
				to = from;
				from = date_sec_change(from, 0, range + 1);
			}
		} else if (to < 0) {
			to = from;
		}
		if (to < from)
			die_at("args.c", 887,
			       "end date cannot come before start date");
		if (filter.type_mask == 0)
			filter.type_mask = TYPE_MASK_ALL;
		io_check_file(path_apts);
		io_check_file(path_todo);
		io_check_file(path_conf);
		load_data(&filter);
		if (!fmt_todo)
			fmt_todo = "%p. %m\n";
		if (!fmt_apt)
			fmt_apt = " - %S -> %E\n\t%m\n";
		if (!fmt_rapt)
			fmt_rapt = " - %S -> %E\n\t%m\n";
		if (!fmt_ev)
			fmt_ev = " * %m\n";
		if (!fmt_rev)
			fmt_rev = " * %m\n";
		add_line = todo_arg(fmt_todo, &limit, &filter);
		date_arg_from_to(from, to, add_line, output_datefmt, fmt_apt,
				 fmt_rapt, fmt_ev, fmt_rev, &limit,
				 !(range_set && range < 0));
		return EXIT_SUCCESS;
	}

	if (next) {
		io_check_file(path_apts);
		io_load_app(NULL);
		next_arg();
		return EXIT_SUCCESS;
	}

	if (grep || purge || filter_cmd) {
		if (filter.type_mask == 0)
			filter.type_mask = TYPE_MASK_ALL;
		if (purge)
			filter.invert = !filter.invert;
		io_check_file(path_apts);
		io_check_file(path_todo);
		io_check_file(path_conf);
		load_data(&filter);
		if (purge || filter_cmd) {
			io_save_apts(path_apts);
			io_save_todo(path_todo);
		} else {
			if (!fmt_todo)
				fmt_todo = "%(raw)";
			if (!fmt_apt)
				fmt_apt = "%(raw)";
			if (!fmt_rapt)
				fmt_rapt = "%(raw)";
			if (!fmt_ev)
				fmt_ev = "%(raw)";
			if (!fmt_rev)
				fmt_rev = "%(raw)";
			grep_data(fmt_ev, fmt_rev, fmt_apt, fmt_rapt, fmt_todo);
		}
		return EXIT_SUCCESS;
	}

	if (export) {
		if (filter.type_mask == 0)
			filter.type_mask = TYPE_MASK_ALL;
		io_check_file(path_apts);
		io_check_file(path_todo);
		load_data(&filter);
		io_export_data(xfmt_pcal, export_uid);
		return EXIT_SUCCESS;
	}

	if (import) {
		int ret;
		io_check_file(path_apts);
		io_check_file(path_todo);
		load_data(NULL);
		if (dump_imported) {
			if (!fmt_todo)
				fmt_todo = "%(raw)";
			if (!fmt_apt)
				fmt_apt = "%(raw)";
			if (!fmt_rapt)
				fmt_rapt = "%(raw)";
			if (!fmt_ev)
				fmt_ev = "%(raw)";
			if (!fmt_rev)
				fmt_rev = "%(raw)";
		} else {
			fmt_todo = fmt_apt = fmt_rapt = fmt_ev = fmt_rev = NULL;
		}
		ret = io_import_data(ifile, dump_imported, fmt_ev, fmt_rev,
				     fmt_apt, fmt_rapt, fmt_todo);
		io_save_apts(path_apts);
		io_save_todo(path_todo);
		return ret ? EXIT_SUCCESS : EXIT_FAILURE;
	}

	if (gc) {
		io_check_file(path_apts);
		io_check_file(path_todo);
		load_data(NULL);
		note_gc();
		return EXIT_SUCCESS;
	}

	return EXIT_SUCCESS;
}
EOF
echo ok"}

