static struct day_item *items;
static int nitems, capitems;

static void day_add(int type, time_t start, void *item)
{
	if (nitems == capitems) {
		capitems = capitems ? capitems * 2 : 32;
		items = xrealloc(items, capitems * sizeof(*items));
	}
	items[nitems].type = type;
	items[nitems].start = start;
	items[nitems].item = item;
	nitems++;
}

static const char *item_mesg(struct day_item *d)
{
	switch (d->type) {
	case DI_APPT:
		return ((struct apoint *)d->item)->mesg;
	case DI_EVNT:
		return ((struct event *)d->item)->mesg;
	case DI_RECUR_APPT:
		return ((struct recur_apoint *)d->item)->mesg;
	case DI_RECUR_EVNT:
		return ((struct recur_event *)d->item)->mesg;
	}
	return "";
}

static int item_state(struct day_item *d)
{
	if (d->type == DI_APPT)
		return ((struct apoint *)d->item)->state;
	if (d->type == DI_RECUR_APPT)
		return ((struct recur_apoint *)d->item)->state;
	return 0;
}

static int is_appt(int t)
{
	return t == DI_APPT || t == DI_RECUR_APPT;
}

static int is_evnt(int t)
{
	return t == DI_EVNT || t == DI_RECUR_EVNT;
}

static int day_cmp(struct day_item *a, struct day_item *b)
{
	if (is_appt(a->type) && is_appt(b->type)) {
		int as, bs;
		if (a->start < b->start)
			return -1;
		if (a->start > b->start)
			return 1;
		as = item_state(a);
		bs = item_state(b);
		if ((as & APOINT_NOTIFY) && !(bs & APOINT_NOTIFY))
			return -1;
		if (!(as & APOINT_NOTIFY) && (bs & APOINT_NOTIFY))
			return 1;
		return strcmp(item_mesg(a), item_mesg(b));
	} else if (is_evnt(a->type) && is_evnt(b->type)) {
		return strcmp(item_mesg(a), item_mesg(b));
	}
	return a->type - b->type;
}

/* Stable insertion sort (lists are small). */
static void day_sort(void)
{
	int i, j;
	for (i = 1; i < nitems; i++) {
		struct day_item x = items[i];
		for (j = i - 1; j >= 0 && day_cmp(&items[j], &x) > 0; j--)
			items[j + 1] = items[j];
		items[j + 1] = x;
	}
}

