			day_add(DI_RECUR_EVNT, occ, r);
	}
	for (i = 0; i < elist.n; i++) {
		struct event *e = elist.v[i];
		if (event_inday(e, date))
			day_add(DI_EVNT, e->day, e);
	}
	if (include_recur_apts) {
		for (i = 0; i < ralist.n; i++) {
			struct recur_apoint *r = ralist.v[i];
			if (recur_apoint_find_occurrence(r, date, &occ))
				day_add(DI_RECUR_APPT, occ, r);
		}
	}
	for (i = 0; i < alist.n; i++) {
		struct apoint *a = alist.v[i];
		if (apoint_inday(a, date))
			day_add(DI_APPT, a->start, a);
	}
	day_sort();
}

int day_item_count(void)
{
	return nitems;
}

struct day_item *day_get_item(int i)
{
	return &items[i];
}
