#include "calcurse.h"
#include <ctype.h>
#include <strings.h>
#include <unistd.h>

#define ICAL_BUFSIZ 8192

enum { ICAL_VEVENT, ICAL_VTODO };
enum { VAL_DATETIME, VAL_DATE };

struct reader {
	FILE *f;
	char buf[ICAL_BUFSIZ];
	char lstore[ICAL_BUFSIZ];
	unsigned *lineno;
};

static int starts_with_ci(const char *s, const char *prefix)
{
	return strncasecmp(s, prefix, strlen(prefix)) == 0;
}

static void strip_eol(char *s)
{
	char *eol = strchr(s, '\n');
	if (eol) {
		if (eol > s && *(eol - 1) == '\r')
			*(eol - 1) = '\0';
		else
			*eol = '\0';
	}
}

static void reader_init(struct reader *r)
{
	r->buf[0] = r->lstore[0] = '\0';
	if (fgets(r->lstore, ICAL_BUFSIZ, r->f)) {
		(*r->lineno)++;
		strip_eol(r->lstore);
	}
}

static int reader_readline(struct reader *r)
{
	snprintf(r->buf, ICAL_BUFSIZ, "%s", r->lstore);
	while (fgets(r->lstore, ICAL_BUFSIZ, r->f) != NULL) {
		(*r->lineno)++;
		strip_eol(r->lstore);
		if (*r->lstore != ' ' && *r->lstore != '\t')
			break;
		strncat(r->buf, r->lstore + 1,
			ICAL_BUFSIZ - strlen(r->buf) - 1);
	}
	if (feof(r->f)) {
		*r->lstore = '\0';
		if (*r->buf == '\0')
			return 0;
	}
	return 1;
}

/*
 * Property line parsing: NAME[;PARAM=VAL...]:VALUE
 */
struct prop {
	char *value;		/* pointer into a copy, NULL if malformed */
	int type;		/* VAL_DATE or VAL_DATETIME */
	char *tzid;		/* NULL if absent */
	int tzid_set;
	char *copy;
};

static void prop_free(struct prop *p)
{
	free(p->copy);
	free(p->tzid);
	memset(p, 0, sizeof(*p));
}

static void prop_parse(const char *line, struct prop *p)
{
	char *s, *q, *colon = NULL, *semi = NULL;
	int inq = 0, value_seen = 0;

	memset(p, 0, sizeof(*p));
	p->copy = s = xstrdup(line);
	p->type = VAL_DATETIME;
	for (q = s; *q; q++) {
		if (*q == '"')
			inq = !inq;
		else if (!inq && *q == ':') {
			colon = q;
			break;
		} else if (!inq && *q == ';' && !semi)
			semi = q;
	}
	if (!colon) {
		p->value = NULL;
		return;
	}
	*colon = '\0';
	p->value = colon + 1;
	if (semi) {
		/* walk the parameters */
		char *param = semi + 1;
		while (param && *param) {
			char *end = param, *eq;
			inq = 0;
			while (*end && (inq || *end != ';')) {
				if (*end == '"')
					inq = !inq;
				end++;
			}
			if (*end)
				*end++ = '\0';
			else
				end = NULL;
			eq = strchr(param, '=');
			if (eq) {
				*eq = '\0';
				if (!strcmp(param, "VALUE") && !value_seen) {
					value_seen = 1;
					p->type = !strcmp(eq + 1, "DATE") ?
						  VAL_DATE : VAL_DATETIME;
				} else if (!strcmp(param, "TZID") &&
					   !p->tzid_set) {
					p->tzid_set = 1;
					if (eq[1] != '"')
						p->tzid = xstrdup(eq + 1);
				}
			}
			param = end;
		}
	}
}

/* Parse a date or date-time value.  Returns -1 on error. */
static time_t parse_datetime_value(const char *s, int type)
{
	unsigned y, m, d, hh, mm, ss;
	char c;
	int n;
	struct tm t;

	n = sscanf(s, "%04u%02u%02uT%02u%02u%02u%c", &y, &m, &d, &hh, &mm,
		   &ss, &c);
	if (type == VAL_DATE) {
		if (n != 3)
			return -1;
		return date2sec((int)y, (int)m, (int)d, 0, 0);
	}
	if (n < 6)
		return -1;
	if (n == 7 && c == 'Z') {
		time_t u;
		memset(&t, 0, sizeof(t));
		t.tm_year = (int)y - 1900;
		t.tm_mon = (int)m - 1;
		t.tm_mday = (int)d;
		t.tm_hour = (int)hh;
		t.tm_min = (int)mm;
		t.tm_sec = 0;
		u = timegm(&t);
		return u;
	}
	return date2sec((int)y, (int)m, (int)d, (int)hh, (int)mm);
}

/* Unescape a TEXT value.  Returns NULL if malformed. */
static char *unescape_text(const char *s, int newline_as_space)
{
	char *out = xmalloc(strlen(s) + 1), *o = out;
	for (; *s; s++) {
		if (*s == '\\') {
			s++;
			switch (*s) {
			case 'n':
			case 'N':
				*o++ = newline_as_space ? ' ' : '\n';
				break;
			case '\\':
			case ',':
			case ';':
				*o++ = *s;
				break;
			default:
				free(out);
				return NULL;
			}
		} else if (*s == ',' || *s == ';') {
			free(out);
			return NULL;
		} else {
			*o++ = *s;
		}
	}
	*o = '\0';
	return out;
}

/* Indent continuation lines of a multi-line field. */
static char *indent_lines(const char *s)
{
	size_t n = 1, i;
	char *out, *o;
	for (i = 0; s[i]; i++)
		n += (s[i] == '\n') ? 5 : 1;
	out = o = xmalloc(n);
	for (; *s; s++) {
		*o++ = *s;
		if (*s == '\n') {
			memcpy(o, "    ", 4);
			o += 4;
		}
	}
	*o = '\0';
	return out;
}

static long durtime(const char *p)
{
	int br = 0;
	unsigned hour = 0, min = 0, sec = 0;

	if (*p != 'T')
		return 0;
	p++;
	if (strchr(p, 'H')) {
		if (sscanf(p, "%uH%n", &hour, &br) != 1)
			return 0;
		p += br;
	}
	if (strchr(p, 'M')) {
		if (sscanf(p, "%uM%n", &min, &br) != 1)
			return 0;
		p += br;
	}
	if (strchr(p, 'S')) {
		if (sscanf(p, "%uS%n", &sec, &br) != 1)
			return 0;
		p += br;
	}
	return (long)hour * HOURINSEC + (long)min * MININSEC + sec;
}

/* Parse a duration; returns <= 0 on error. */
static long parse_duration(const char *s, int type)
{
	const char *p;
	unsigned n;
	char c;
	int br = 0;

	p = strchr(s, 'P');
	if (!p)
		return -1;
	if (p > s && *(p - 1) == '-')
		return -1;
	p++;
	if (*p == 'T') {
		if (type == VAL_DATE)
			return -1;
		return durtime(p);
	}
	if (sscanf(p, "%u%c%n", &n, &c, &br) != 2)
		return -1;
	if (c == 'W')
		return (long)n * WEEKINDAYS * DAYINSEC;
	if (c == 'D') {
		if (type == VAL_DATE)
			return (long)n * DAYINSEC;
		return (long)n * DAYINSEC + durtime(p + br);
	}
	return -1;
}

