echo ok"}

actions.command:
cat > /workspace/src/ical.c <<'EOF'
#include "calcurse.h"
#include <ctype.h>
#include <strings.h>
#include <unistd.h>

#define ICAL_BUFSIZ 8192

enum { ICAL_VEVENT, ICAL_VTODO };
enum { VAL_DATETIME, VAL_DATE };

struct reader {
	FILE *f;
	char buf[ICAL_BUFSIZ];
	char lstore[ICAL_BUFSIZ];
	unsigned *lineno;
};

static int starts_with_ci(const char *s, const char *prefix)
{
	return strncasecmp(s, prefix, strlen(prefix)) == 0;
}

static void strip_eol(char *s)
{
	char *eol = strchr(s, '\n');
	if (eol) {
		if (eol > s && *(eol - 1) == '\r')
			*(eol - 1) = '\0';
		else
			*eol = '\0';
	}
}

static void reader_init(struct reader *r)
{
	r->buf[0] = r->lstore[0] = '\0';
	if (fgets(r->lstore, ICAL_BUFSIZ, r->f)) {
		(*r->lineno)++;
		strip_eol(r->lstore);
	}
}

static int reader_readline(struct reader *r)
{
	snprintf(r->buf, ICAL_BUFSIZ, "%s", r->lstore);
	while (fgets(r->lstore, ICAL_BUFSIZ, r->f) != NULL) {
		(*r->lineno)++;
		strip_eol(r->lstore);
		if (*r->lstore != ' ' && *r->lstore != '\t')
			break;
		strncat(r->buf, r->lstore + 1,
			ICAL_BUFSIZ - strlen(r->buf) - 1);
	}
	if (feof(r->f)) {
		*r->lstore = '\0';
		if (*r->buf == '\0')
			return 0;
	}
	return 1;
}

/*
 * Property line parsing: NAME[;PARAM=VAL...]:VALUE
 */
struct prop {
	char *value;		/* pointer into a copy, NULL if malformed */
	int type;		/* VAL_DATE or VAL_DATETIME */
	char *tzid;		/* NULL if absent */
	int tzid_set;
	char *copy;
};

static void prop_free(struct prop *p)
{
	free(p->copy);
	free(p->tzid);
	memset(p, 0, sizeof(*p));
}

static void prop_parse(const char *line, struct prop *p)
{
	char *s, *q, *colon = NULL, *semi = NULL;
	int inq = 0, value_seen = 0;

	memset(p, 0, sizeof(*p));
	p->copy = s = xstrdup(line);
	p->type = VAL_DATETIME;
	for (q = s; *q; q++) {
		if (*q == '"')
			inq = !inq;
		else if (!inq && *q == ':') {
			colon = q;
			break;
		} else if (!inq && *q == ';' && !semi)
			semi = q;
	}
	if (!colon) {
		p->value = NULL;
		return;
	}
	*colon = '\0';
	p->value = colon + 1;
	if (semi) {
		/* walk the parameters */
		char *param = semi + 1;
		while (param && *param) {
			char *end = param, *eq;
			inq = 0;
			while (*end && (inq || *end != ';')) {
				if (*end == '"')
					inq = !inq;
				end++;
			}
			if (*end)
				*end++ = '\0';
			else
				end = NULL;
			eq = strchr(param, '=');
			if (eq) {
				*eq = '\0';
				if (!strcmp(param, "VALUE") && !value_seen) {
					value_seen = 1;
					p->type = !strcmp(eq + 1, "DATE") ?
						  VAL_DATE : VAL_DATETIME;
				} else if (!strcmp(param, "TZID") &&
					   !p->tzid_set) {
					p->tzid_set = 1;
					if (eq[1] != '"')
						p->tzid = xstrdup(eq + 1);
				}
			}
			param = end;
		}
	}
}

/* Parse a date or date-time value.  Returns -1 on error. */
static time_t parse_datetime_value(const char *s, int type)
{
	unsigned y, m, d, hh, mm, ss;
	char c;
	int n;
	struct tm t;

	n = sscanf(s, "%04u%02u%02uT%02u%02u%02u%c", &y, &m, &d, &hh, &mm,
		   &ss, &c);
	if (type == VAL_DATE) {
		if (n != 3)
			return -1;
		return date2sec((int)y, (int)m, (int)d, 0, 0);
	}
	if (n < 6)
		return -1;
	if (n == 7 && c == 'Z') {
		time_t u;
		memset(&t, 0, sizeof(t));
		t.tm_year = (int)y - 1900;
		t.tm_mon = (int)m - 1;
		t.tm_mday = (int)d;
		t.tm_hour = (int)hh;
		t.tm_min = (int)mm;
		t.tm_sec = 0;
		u = timegm(&t);
		return u;
	}
	return date2sec((int)y, (int)m, (int)d, (int)hh, (int)mm);
}

/* Unescape a TEXT value.  Returns NULL if malformed. */
static char *unescape_text(const char *s, int newline_as_space)
{
	char *out = xmalloc(strlen(s) + 1), *o = out;
	for (; *s; s++) {
		if (*s == '\\') {
			s++;
			switch (*s) {
			case 'n':
			case 'N':
				*o++ = newline_as_space ? ' ' : '\n';
				break;
			case '\\':
			case ',':
			case ';':
				*o++ = *s;
				break;
			default:
				free(out);
				return NULL;
			}
		} else if (*s == ',' || *s == ';') {
			free(out);
			return NULL;
		} else {
			*o++ = *s;
		}
	}
	*o = '\0';
	return out;
}

/* Indent continuation lines of a multi-line field. */
static char *indent_lines(const char *s)
{
	size_t n = 1, i;
	char *out, *o;
	for (i = 0; s[i]; i++)
		n += (s[i] == '\n') ? 5 : 1;
	out = o = xmalloc(n);
	for (; *s; s++) {
		*o++ = *s;
		if (*s == '\n') {
			memcpy(o, "    ", 4);
			o += 4;
		}
	}
	*o = '\0';
	return out;
}

static long durtime(const char *p)
{
	int br = 0;
	unsigned hour = 0, min = 0, sec = 0;

	if (*p != 'T')
		return 0;
	p++;
	if (strchr(p, 'H')) {
		if (sscanf(p, "%uH%n", &hour, &br) != 1)
			return 0;
		p += br;
	}
	if (strchr(p, 'M')) {
		if (sscanf(p, "%uM%n", &min, &br) != 1)
			return 0;
		p += br;
	}
	if (strchr(p, 'S')) {
		if (sscanf(p, "%uS%n", &sec, &br) != 1)
			return 0;
		p += br;
	}
	return (long)hour * HOURINSEC + (long)min * MININSEC + sec;
}

/* Parse a duration; returns <= 0 on error. */
static long parse_duration(const char *s, int type)
{
	const char *p;
	unsigned n;
	char c;
	int br = 0;

	p = strchr(s, 'P');
	if (!p)
		return -1;
	if (p > s && *(p - 1) == '-')
		return -1;
	p++;
	if (*p == 'T') {
		if (type == VAL_DATE)
			return -1;
		return durtime(p);
	}
	if (sscanf(p, "%u%c%n", &n, &c, &br) != 2)
		return -1;
	if (c == 'W')
		return (long)n * WEEKINDAYS * DAYINSEC;
	if (c == 'D') {
		if (type == VAL_DATE)
			return (long)n * DAYINSEC;
		return (long)n * DAYINSEC + durtime(p + br);
	}
	return -1;
}

static FILE *g_log;
static unsigned g_skipped_count;

static void ical_log(int type, unsigned line, const char *msg)
{
	if (!g_log)
		return;
	fprintf(g_log, "%s [%u]: %s\n",
		type == ICAL_VEVENT ? "VEVENT" : "VTODO", line, msg);
}

static void skip_to_end(struct reader *r, const char *endtag)
{
	while (reader_readline(r)) {
		if (starts_with_ci(r->buf, endtag))
			break;
	}
}

struct text_fields {
	char *mesg;
	char *desc;
	char *loc;
	char **comm;
	int ncomm;
};

static void text_fields_free(struct text_fields *t)
{
	int i;
	free(t->mesg);
	free(t->desc);
	free(t->loc);
	for (i = 0; i < t->ncomm; i++)
		free(t->comm[i]);
	free(t->comm);
	memset(t, 0, sizeof(*t));
}

/*
 * Handle text properties.  Returns NULL if the line is not a text
 * property or was processed, an error message otherwise.  *handled is
 * set if the line was a text property.
 */
static const char *handle_text(const char *line, struct text_fields *t,
			       int *handled)
{
	struct prop p;
	char *v;

	*handled = 1;
	if (starts_with_ci(line, "SUMMARY")) {
		prop_parse(line, &p);
		if (!p.value) {
			prop_free(&p);
			return "malformed summary line.";
		}
		v = unescape_text(p.value, 1);
		prop_free(&p);
		if (!v)
			return "malformed summary.";
		free(t->mesg);
		t->mesg = v;
		return NULL;
	}
	if (starts_with_ci(line, "DESCRIPTION")) {
		if (t->desc)
			return "only one description allowed.";
		prop_parse(line, &p);
		if (!p.value) {
			prop_free(&p);
			return "malformed description line.";
		}
		v = unescape_text(p.value, 0);
		prop_free(&p);
		if (!v)
			return "malformed description.";
		t->desc = v;
		return NULL;
	}
	if (starts_with_ci(line, "LOCATION")) {
		if (t->loc)
			return "only one location allowed.";
		prop_parse(line, &p);
		if (!p.value) {
			prop_free(&p);
			return "malformed location line.";
		}
		v = unescape_text(p.value, 0);
		prop_free(&p);
		if (!v)
			return "malformed location.";
		t->loc = v;
		return NULL;
	}
	if (starts_with_ci(line, "COMMENT")) {
		prop_parse(line, &p);
		if (!p.value) {
			prop_free(&p);
			return "malformed comment line.";
		}
		v = unescape_text(p.value, 0);
		prop_free(&p);
		if (!v)
			return "malformed comment.";
		t->comm = xrealloc(t->comm, sizeof(char *) * (t->ncomm + 1));
		t->comm[t->ncomm++] = v;
		return NULL;
	}
	*handled = 0;
	return NULL;
}

static char *build_note(struct text_fields *t, const char *tzid,
			int multiday)
{
	size_t cap = 256;
	char *note;
	int i;

	if (!t->desc && !t->loc && !t->ncomm && !tzid && !multiday)
		return NULL;

#define ADD(str)                                                        \
	do {                                                            \
		const char *s__ = (str);                                \
		size_t l__ = strlen(s__);                               \
		while (strlen(note) + l__ + 1 > cap)                    \
			cap *= 2;                                       \
		note = xrealloc(note, cap);                             \
		strcat(note, s__);                                      \
	} while (0)

	note = xmalloc(cap);
	note[0] = '\0';
	if (t->desc) {
		ADD(t->desc);
		ADD("\n");
	}
	if (t->loc || t->ncomm || tzid || multiday) {
		ADD("-- \n");
		if (t->loc) {
			char *x = indent_lines(t->loc);
			ADD("Location: ");
			ADD(x);
			ADD("\n");
			free(x);
		}
		for (i = 0; i < t->ncomm; i++) {
			char *x = indent_lines(t->comm[i]);
			ADD("Comment: ");
			ADD(x);
			ADD("\n");
			free(x);
		}
		if (tzid) {
			ADD("Import: TZID=");
			ADD(tzid);
			ADD("\n");
		}
		if (multiday)
			ADD("Import: multi-day event changed to one-day event\n");
	}
#undef ADD
	{
		char *id = generate_note(note);
		free(note);
		return id;
	}
}

/* Parse a comma separated list of integers. */
static int parse_int_list(const char *s, struct ilist *l)
{
	const char *p = s;
	int v, n;

	if (*p == '\0' || *p == ';')
		return 1;
	for (;;) {
		if (sscanf(p, "%d%n", &v, &n) != 1)
			return 0;
		p += n;
		ilist_add(l, v);
		if (*p == ',') {
			p++;
			if (*p == '\0' || *p == ';')
				return 1;
			continue;
		}
		if (*p == '\0' || *p == ';')
			return 1;
		return 0;
	}
}

static int parse_byday_list(const char *s, struct ilist *l)
{
	static const char *days[] = { "SU", "MO", "TU", "WE", "TH", "FR",
		"SA" };
	char tok[ICAL_BUFSIZ];
	const char *p;
	int i, len = 0;

	while (s[len] && s[len] != ';' && !isspace((unsigned char)s[len]) &&
	       len < ICAL_BUFSIZ - 1) {
		tok[len] = s[len];
		len++;
	}
	tok[len] = '\0';
	if (len == 0)
		return 1;
	p = tok;
	for (;;) {
		int n = 0, num = 0, sign = 1, wd = -1;
		const char *q = p;
		if (*q == '+' || *q == '-') {
			if (*q == '-')
				sign = -1;
			q++;
		}
		if (isdigit((unsigned char)*q)) {
			while (isdigit((unsigned char)*q)) {
				num = num * 10 + (*q - '0');
				q++;
			}
			n = 1;
		} else if (q != p) {
			return 0;
		}
		for (i = 0; i < 7; i++) {
			if (!strncmp(q, days[i], 2)) {
				wd = i;
				break;
			}
		}
		if (wd < 0)
			return 0;
		if (n && num)
			ilist_add(l, sign * (num * 7 + wd));
		else
			ilist_add(l, wd);
		p = strchr(q, ',');
		if (!p)
			break;
		p++;
		if (!*p)
			break;
	}
	return 1;
}

/*
 * Parse an RRULE value.  Returns an error message or NULL.
 */
static const char *parse_rrule(const char *value, int type, struct rpt *rpt,
			       int *count)
{
	const char *p;
	char tok[64];
	int i;

	*count = 0;
	p = strstr(value, "FREQ=");
	if (!p)
		return "frequency absent in rrule.";
	p += 5;
	for (i = 0; p[i] && p[i] != ';' && i < 63; i++)
		tok[i] = p[i];
	tok[i] = '\0';
	if (!tok[0])
		return "frequency not set in rrule.";
	if (!strcmp(tok, "DAILY"))
		rpt->type = RECUR_DAILY;
	else if (!strcmp(tok, "WEEKLY"))
		rpt->type = RECUR_WEEKLY;
	else if (!strcmp(tok, "MONTHLY"))
		rpt->type = RECUR_MONTHLY;
	else if (!strcmp(tok, "YEARLY"))
		rpt->type = RECUR_YEARLY;
	else
		return "rrule frequency not supported.";

	rpt->freq = 1;
	p = strstr(value, "INTERVAL=");
	if (p) {
		int v;
		if (sscanf(p + 9, "%d", &v) != 1)
			return "invalid interval.";
		rpt->freq = v;
	}

	{
		const char *u = strstr(value, "UNTIL=");
		const char *c = strstr(value, "COUNT=");
		if (u && c)
			return "either until or count.";
		if (u) {
			char buf[128];
			time_t t;
			u += 6;
			for (i = 0; u[i] && u[i] != ';' && i < 127; i++)
				buf[i] = u[i];
			buf[i] = '\0';
			if (!buf[0])
				return "missing until value.";
			t = parse_datetime_value(buf, type);
			if (t == -1)
				return "invalid until format.";
			rpt->until = t;
		} else if (c) {
			int v;
			if (sscanf(c + 6, "%d", &v) != 1 || v == 0)
				return "invalid count value.";
			*count = v;
		}
	}

	p = strstr(value, "BYMONTH=");
	if (p && !parse_int_list(p + 8, &rpt->bymonth))
		return "invalid bymonth list.";
	p = strstr(value, "BYMONTHDAY=");
	if (p && !parse_int_list(p + 11, &rpt->bymonthday))
		return "invalid bymonthday list.";
	p = strstr(value, "BYDAY=");
	if (p && !parse_byday_list(p + 6, &rpt->bywday))
		return "invalid byday list.";
	return NULL;
}

static void exc_add_sorted(struct ilist *exc, time_t t)
{
	int i, pos = exc->n;
	ilist_add(exc, 0);
	for (i = 0; i < exc->n - 1; i++) {
		if ((time_t)exc->v[i] > t) {
			pos = i;
			break;
		}
	}
	for (i = exc->n - 1; i > pos; i--)
		exc->v[i] = exc->v[i - 1];
	exc->v[pos] = (long)t;
}

static const char *parse_exdate(const char *line, int type, struct ilist *exc)
{
	struct prop p;
	const char *s;
	char buf[128];
	int i;

	prop_parse(line, &p);
	if (!p.value) {
		prop_free(&p);
		return "malformed exceptions line.";
	}
	if (p.type != type) {
		prop_free(&p);
		return "invalid exception date value type.";
	}
	s = p.value;
	for (;;) {
		time_t t;
		for (i = 0; s[i] && s[i] != ',' && s[i] != ';' &&
		     !isspace((unsigned char)s[i]) && i < 127; i++)
			buf[i] = s[i];
		buf[i] = '\0';
		t = parse_datetime_value(buf, type);
		if (t == -1) {
			prop_free(&p);
			return "invalid exception.";
		}
		exc_add_sorted(exc, update_time_in_date(t, 0, 0));
		s += i;
		if (*s != ',')
			break;
		s++;
	}
	prop_free(&p);
	return NULL;
}

struct dump_fmts {
	const char *ev, *rev, *apt, *rapt, *todo;
};
static struct dump_fmts g_fmt;

static void ical_read_event(struct reader *r, unsigned *noevents,
			    unsigned *noapoints, unsigned *noskipped)
{
	const unsigned itemline = *r->lineno - !feof(r->f);
	struct text_fields t;
	char *l_start = NULL, *l_end = NULL, *l_dur = NULL, *l_rrule = NULL;
	char **l_exc = NULL;
	int n_exc = 0, i;
	int skip_alarm = 0, has_alarm = 0;
	const char *err = NULL;
	struct prop ps;
	time_t start = 0, end = 0;
	long dur = 0;
	int type = VAL_DATETIME;
	int has_rrule = 0, count = 0;
	struct rpt rpt;
	char *tzid = NULL;

	memset(&t, 0, sizeof(t));
	memset(&ps, 0, sizeof(ps));
	rpt_init(&rpt);

	while (reader_readline(r)) {
		const char *line = r->buf;
		int handled;

		if (skip_alarm) {
			if (starts_with_ci(line, "END:VALARM"))
				skip_alarm = 0;
			continue;
		}
		if (starts_with_ci(line, "END:VEVENT"))
			goto finalize;
		if (starts_with_ci(line, "DTSTART")) {
			free(l_start);
			l_start = xstrdup(line);
		} else if (starts_with_ci(line, "DTEND")) {
			free(l_end);
			l_end = xstrdup(line);
		} else if (starts_with_ci(line, "DURATION")) {
			free(l_dur);
			l_dur = xstrdup(line);
		} else if (starts_with_ci(line, "RRULE")) {
			free(l_rrule);
			l_rrule = xstrdup(line);
		} else if (starts_with_ci(line, "EXDATE")) {
			l_exc = xrealloc(l_exc, sizeof(char *) * (n_exc + 1));
			l_exc[n_exc++] = xstrdup(line);
		} else if (starts_with_ci(line, "BEGIN:VALARM")) {
			has_alarm = 1;
			skip_alarm = 1;
		} else {
			err = handle_text(line, &t, &handled);
			if (err) {
				ical_log(ICAL_VEVENT, itemline, err);
				(*noskipped)++;
				skip_to_end(r, "END:VEVENT");
				goto cleanup;
			}
		}
	}
	ical_log(ICAL_VEVENT, itemline,
		 "The ical file seems to be malformed. "
		 "The end of item was not found.");
	(*noskipped)++;
	goto cleanup;

finalize:
	if (!l_start) {
		err = "item start date not defined.";
		goto fail;
	}
	prop_parse(l_start, &ps);
	if (!ps.value) {
		err = "malformed start time line.";
		goto fail;
	}
	type = ps.type;
	start = parse_datetime_value(ps.value, type);
	if (start == -1) {
		err = "invalid or malformed event start time.";
		goto fail;
	}
	if (type == VAL_DATETIME && ps.tzid)
		tzid = xstrdup(ps.tzid);

	if (l_end) {
		struct prop pe;
		prop_parse(l_end, &pe);
		if (!pe.value) {
			prop_free(&pe);
			err = "malformed end time line.";
			goto fail;
		}
		if (pe.type != type) {
			prop_free(&pe);
			err = "invalid end time value type.";
			goto fail;
		}
		end = parse_datetime_value(pe.value, type);
		prop_free(&pe);
		if (end == -1) {
			err = "malformed event end time.";
			goto fail;
		}
		if (end < start) {
			err = "end must be later than start.";
			goto fail;
		}
		dur = end - start;
	}
	if (l_dur) {
		struct prop pd;
		if (l_end) {
			err = "either end or duration.";
			goto fail;
		}
		prop_parse(l_dur, &pd);
		if (!pd.value) {
			prop_free(&pd);
			err = "malformed duration line.";
			goto fail;
		}
		dur = parse_duration(pd.value, type);
		prop_free(&pd);
		if (dur <= 0) {
			err = "invalid duration.";
			goto fail;
		}
	}
	if (l_rrule) {
		struct prop pr;
		prop_parse(l_rrule, &pr);
		if (!pr.value) {
			prop_free(&pr);
			err = "malformed recurrence line.";
			goto fail;
		}
		err = parse_rrule(pr.value, type, &rpt, &count);
		prop_free(&pr);
		if (err)
			goto fail;
		has_rrule = 1;
	}
	if (n_exc) {
		if (!has_rrule) {
			err = "exception date, but no recurrence rule.";
			goto fail;
		}
		for (i = 0; i < n_exc; i++) {
			err = parse_exdate(l_exc[i], type, &rpt.exc);
			if (err)
				goto fail;
		}
	}

	{
		int multiday = 0;
		char *note;
		const char *mesg = t.mesg ? t.mesg : "(empty)";
		time_t until_t = rpt.until;

		if (has_rrule) {
			rpt.until = 0;
			if (until_t) {
				time_t uday = update_time_in_date(until_t, 0, 0);
				time_t o;
				rpt.until = uday;
				if (recur_candidate(start, &rpt, uday)) {
					struct tm lt;
					localtime_r(&start, &lt);
					o = update_time_in_date(uday, lt.tm_hour,
								lt.tm_min);
					if (o > until_t)
						uday = date_sec_change(uday, 0, -1);
				}
				rpt.until = uday;
			}
			{
				struct rpt chk;
				rpt_copy(&chk, &rpt);
				chk.until = 0;
				if (!recur_candidate(start, &chk, start) ||
				    (rpt.until && rpt.until <
				     update_time_in_date(start, 0, 0))) {
					char d[64], msg[128];
					rpt_free(&chk);
					format_date_numeric(d, sizeof(d), start,
							    conf.input_datefmt);
					snprintf(msg, sizeof(msg),
						 "rrule does not match start day (%s).",
						 d);
					ical_log(ICAL_VEVENT, itemline, msg);
					(*noskipped)++;
					goto cleanup;
				}
				rpt_free(&chk);
			}
			if (count > 0) {
				time_t nth;
				if (recur_nth_occurrence(start, &rpt, count,
							 &nth))
					rpt.until = update_time_in_date(nth, 0,
									0);
			}
		}

		if (type == VAL_DATE) {
			if (dur > DAYINSEC) {
				multiday = 1;
				if (!has_rrule) {
					has_rrule = 1;
					rpt.type = RECUR_DAILY;
					rpt.freq = 1;
					rpt.until = date_sec_change(start, 0,
						(int)(dur / DAYINSEC) - 1);
				}
			}
		}

		note = build_note(&t, tzid, multiday);

		if (type == VAL_DATE) {
			if (has_rrule) {
				struct recur_event *re =
					recur_event_new(mesg, note, start, 1,
							&rpt);
				plist_add_sorted(&relist, re, recur_event_cmp);
				if (g_fmt.rev)
					print_recur_event(g_fmt.rev, re->day, re);
			} else {
				struct event *e = event_new(mesg, note, start, 1);
				plist_add_sorted(&elist, e, event_cmp);
				if (g_fmt.ev)
					print_event(g_fmt.ev, e->day, e);
			}
			(*noevents)++;
		} else {
			char state = has_alarm ? APOINT_NOTIFY : 0;
			if (has_rrule) {
				struct recur_apoint *ra = recur_apoint_new(
					mesg, note, start, dur, state, &rpt);
				plist_add_sorted(&ralist, ra, recur_apoint_cmp);
				if (g_fmt.rapt)
					print_recur_apoint(g_fmt.rapt,
						update_time_in_date(ra->start, 0, 0),
						ra->start, ra);
			} else {
				struct apoint *a = apoint_new(mesg, note, start,
							      dur, state);
				plist_add_sorted(&alist, a, apoint_cmp);
				if (g_fmt.apt)
					print_apoint(g_fmt.apt,
						update_time_in_date(a->start, 0, 0),
						a);
			}
			(*noapoints)++;
		}
		free(note);
	}
	goto cleanup;

fail:
	ical_log(ICAL_VEVENT, itemline, err);
	(*noskipped)++;
cleanup:
	prop_free(&ps);
	text_fields_free(&t);
	free(l_start);
	free(l_end);
	free(l_dur);
	free(l_rrule);
	for (i = 0; i < n_exc; i++)
		free(l_exc[i]);
	free(l_exc);
	free(tzid);
	rpt_free(&rpt);
}

static void ical_read_todo(struct reader *r, unsigned *notodos,
			   unsigned *noskipped)
{
	const unsigned itemline = *r->lineno - !feof(r->f);
	struct text_fields t;
	int skip_alarm = 0, completed = 0, priority = 0;
	const char *err;

	memset(&t, 0, sizeof(t));
	while (reader_readline(r)) {
		const char *line = r->buf;
		int handled;

		if (skip_alarm) {
			if (starts_with_ci(line, "END:VALARM"))
				skip_alarm = 0;
			continue;
		}
		if (starts_with_ci(line, "END:VTODO")) {
			char *note;
			struct todo *td;
			if (!t.mesg) {
				ical_log(ICAL_VTODO, itemline,
					 "could not retrieve item summary.");
				goto cleanup;
			}
			note = build_note(&t, NULL, 0);
			td = todo_new(t.mesg, priority, completed, note);
			plist_add_sorted(&tlist, td, todo_cmp);
			if (g_fmt.todo)
				print_todo(g_fmt.todo, td);
			(*notodos)++;
			free(note);
			goto cleanup;
		}
		if (starts_with_ci(line, "PRIORITY")) {
			int v;
			if (sscanf(line, "PRIORITY:%d", &v) == 1) {
				if (v < 0 || v > 9) {
					ical_log(ICAL_VTODO, itemline,
						 "item priority is invalid (must be between 0 and 9).");
					(*noskipped)++;
					skip_to_end(r, "END:VTODO");
					goto cleanup;
				}
				priority = v;
			}
		} else if (starts_with_ci(line, "STATUS:COMPLETED")) {
			completed = 1;
		} else if (starts_with_ci(line, "BEGIN:VALARM")) {
			skip_alarm = 1;
		} else {
			err = handle_text(line, &t, &handled);
			if (err) {
				ical_log(ICAL_VTODO, itemline, err);
				(*noskipped)++;
				skip_to_end(r, "END:VTODO");
				goto cleanup;
			}
		}
	}
	ical_log(ICAL_VTODO, itemline,
		 "The ical file seems to be malformed. "
		 "The end of item was not found.");
	(*noskipped)++;
cleanup:
	text_fields_free(&t);
}

static int ical_chk_header(struct reader *r, int *major, int *minor)
{
	if (!reader_readline(r))
		return 0;
	if (!starts_with_ci(r->buf, "BEGIN:VCALENDAR"))
		return 0;
	*major = 0;
	*minor = 0;
	while (sscanf(r->buf, "VERSION:%d.%d", major, minor) < 1) {
		if (!reader_readline(r))
			return 0;
	}
	return 1;
}

static void ical_log_init(FILE *log, const char *file, int major, int minor)
{
	char date[64], when[128];
	time_t now = time(NULL);
	struct tm lt;

	if (!log)
		return;
	format_date_numeric(date, sizeof(date), now, conf.input_datefmt);
	localtime_r(&now, &lt);
	snprintf(when, sizeof(when), "%s %02d:%02d", date, lt.tm_hour,
		 lt.tm_min);
	fprintf(log,
		"+-------------------------------------------------------------------+\n"
		"| Calcurse icalendar import log.                                    |\n"
		"|                                                                   |\n"
		"| Import from icalendar file                                        |\n"
		"|       %-60s|\n"
		"| version %d.%d at %s.                                  |\n"
		"|                                                                   |\n"
		"| Items which could not be imported are described below.            |\n"
		"| The log line format is as follows:                                |\n"
		"|                                                                   |\n"
		"|       TYPE [LINE]: DESCRIPTION                                    |\n"
		"|                                                                   |\n"
		"| where:                                                            |\n"
		"|  * TYPE is the item type, 'VEVENT' or 'VTODO'                     |\n"
		"|  * LINE is the line in the import file where the item begins      |\n"
		"|  * DESCRIPTION explains why the item could not be imported        |\n"
		"+-------------------------------------------------------------------+\n\n",
		file, major, minor, when);
}

void ical_import_data(const char *file, FILE *stream, FILE *log,
		      unsigned *events, unsigned *apoints, unsigned *todos,
		      unsigned *lines, unsigned *skipped, const char *fmt_ev,
		      const char *fmt_rev, const char *fmt_apt,
		      const char *fmt_rapt, const char *fmt_todo)
{
	struct reader r;
	int major, minor;

	g_log = log;
	g_skipped_count = 0;
	g_fmt.ev = fmt_ev;
	g_fmt.rev = fmt_rev;
	g_fmt.apt = fmt_apt;
	g_fmt.rapt = fmt_rapt;
	g_fmt.todo = fmt_todo;

	r.f = stream;
	r.lineno = lines;
	reader_init(&r);
	if (!ical_chk_header(&r, &major, &minor)) {
		fflush(stdout);
		fprintf(stderr,
			"ical.c: 1879: Warning: ical header malformed or wrong version number. Aborting...\n");
		return;
	}
	ical_log_init(log, file, major, minor);

	while (reader_readline(&r)) {
		if (starts_with_ci(r.buf, "BEGIN:VEVENT"))
			ical_read_event(&r, events, apoints, skipped);
		else if (starts_with_ci(r.buf, "BEGIN:VTODO"))
			ical_read_todo(&r, todos, skipped);
	}
}

/*
 * Export.
 */
static void ical_escape_print(FILE *f, const char *s)
{
	for (; *s; s++) {
		switch (*s) {
		case ',':
		case ';':
		case '\\':
			fputc('\\', f);
			fputc(*s, f);
			break;
		case '\n':
			fputs("\\n", f);
			break;
		default:
			fputc(*s, f);
		}
	}
}

static void ical_export_note(FILE *f, const char *name)
{
	char *path;
	FILE *fp;
	char *buf = NULL;
	size_t n = 0, cap = 0;
	int c;

	if (!name)
		return;
	path = mkpath(path_notes, name);
	fp = fopen(path, "r");
	free(path);
	if (!fp)
		return;
	while ((c = getc(fp)) != EOF) {
		if (n + 2 > cap) {
			cap = cap ? cap * 2 : 256;
			buf = xrealloc(buf, cap);
		}
		buf[n++] = (char)c;
	}
	fclose(fp);
	if (n == 0) {
		free(buf);
		return;
	}
	buf[n - 1] = '\0';
	fputs("DESCRIPTION:", f);
	ical_escape_print(f, buf);
	fputs("\n", f);
	free(buf);
}

static const char *ical_freq(int type)
{
	switch (type) {
	case RECUR_DAILY:
		return "DAILY";
	case RECUR_WEEKLY:
		return "WEEKLY";
	case RECUR_MONTHLY:
		return "MONTHLY";
	case RECUR_YEARLY:
		return "YEARLY";
	}
	return "";
}

static void ical_export_rrule(FILE *f, struct rpt *r, time_t start,
			      int is_event)
{
	static const char *days[] = { "SU", "MO", "TU", "WE", "TH", "FR",
		"SA" };
	char buf[64];
	struct tm lt;
	int i;

	fprintf(f, "RRULE:FREQ=%s", ical_freq(r->type));
	if (r->freq > 1)
		fprintf(f, ";INTERVAL=%d", r->freq);
	if (r->until) {
		if (is_event) {
			localtime_r(&r->until, &lt);
			strftime(buf, sizeof(buf), "%Y%m%d", &lt);
		} else {
			struct tm st;
			time_t u;
			localtime_r(&start, &st);
			u = update_time_in_date(r->until, st.tm_hour, st.tm_min);
			localtime_r(&u, &lt);
			strftime(buf, sizeof(buf), "%Y%m%dT%H%M%S", &lt);
		}
		fprintf(f, ";UNTIL=%s", buf);
	}
	if (r->bymonth.n) {
		fputs(";BYMONTH=", f);
		for (i = 0; i < r->bymonth.n; i++)
			fprintf(f, "%s%ld", i ? "," : "", r->bymonth.v[i]);
	}
	if (r->bywday.n) {
		fputs(";BYDAY=", f);
		for (i = 0; i < r->bywday.n; i++) {
			long w = r->bywday.v[i];
			long n = w >= 0 ? w / 7 : -((-w) / 7);
			int wd = (int)(w >= 0 ? w % 7 : (-w) % 7);
			if (i)
				fputc(',', f);
			if (n > 0)
				fprintf(f, "+%ld", n);
			else if (n < 0)
				fprintf(f, "%ld", n);
			fputs(days[wd], f);
		}
	}
	if (r->bymonthday.n) {
		fputs(";BYMONTHDAY=", f);
		for (i = 0; i < r->bymonthday.n; i++)
			fprintf(f, "%s%ld", i ? "," : "", r->bymonthday.v[i]);
	}
	fputs("\n", f);
}

static void ical_export_exc(FILE *f, struct ilist *exc, time_t start,
			    int is_event)
{
	char buf[64];
	struct tm lt, st;
	int i;

	if (!exc->n)
		return;
	localtime_r(&start, &st);
	fputs(is_event ? "EXDATE;VALUE=DATE:" : "EXDATE:", f);
	for (i = 0; i < exc->n; i++) {
		time_t t = (time_t)exc->v[i];
		if (!is_event)
			t = update_time_in_date(t, st.tm_hour, st.tm_min);
		localtime_r(&t, &lt);
		strftime(buf, sizeof(buf), "%Y%m%dT%H%M%S", &lt);
		fprintf(f, "%s%s", i ? "," : "", buf);
	}
	fputs("\n", f);
}

static void ical_export_valarm(FILE *f)
{
	fprintf(f, "BEGIN:VALARM\nTRIGGER:-PT%dS\nACTION:DISPLAY\nEND:VALARM\n",
		conf.notify_warning);
}

static void ical_export_uid(FILE *f, char *raw, int export_uid)
{
	if (export_uid) {
		char *h = item_hash(raw);
		fprintf(f, "UID:%s\n", h);
		free(h);
	}
	free(raw);
}

static void print_date_fmt(FILE *f, const char *prefix, time_t t,
			   const char *fmt)
{
	char buf[64];
	struct tm lt;
	localtime_r(&t, &lt);
	strftime(buf, sizeof(buf), fmt, &lt);
	fprintf(f, "%s%s\n", prefix, buf);
}

void ical_export_data(FILE *f, int export_uid)
{
	int i;

	fprintf(f, "BEGIN:VCALENDAR\nVERSION:2.0\n"
		   "PRODID:-//calcurse//NONSGML v%s//EN\n", VERSION);

	for (i = 0; i < relist.n; i++) {
		struct recur_event *r = relist.v[i];
		fputs("BEGIN:VEVENT\n", f);
		ical_export_uid(f, recur_event_tostr(r), export_uid);
		print_date_fmt(f, "DTSTART;VALUE=DATE:", r->day, "%Y%m%d");
		ical_export_rrule(f, &r->rpt, r->day, 1);
		ical_export_exc(f, &r->rpt.exc, r->day, 1);
		fputs("SUMMARY:", f);
		ical_escape_print(f, r->mesg);
		fputs("\n", f);
		ical_export_note(f, r->note);
		fputs("END:VEVENT\n", f);
	}
	for (i = 0; i < elist.n; i++) {
		struct event *e = elist.v[i];
		fputs("BEGIN:VEVENT\n", f);
		ical_export_uid(f, event_tostr(e), export_uid);
		print_date_fmt(f, "DTSTART;VALUE=DATE:", e->day, "%Y%m%d");
		fputs("SUMMARY:", f);
		ical_escape_print(f, e->mesg);
		fputs("\n", f);
		ical_export_note(f, e->note);
		fputs("END:VEVENT\n", f);
	}
	for (i = 0; i < ralist.n; i++) {
		struct recur_apoint *r = ralist.v[i];
		long d = r->dur;
		fputs("BEGIN:VEVENT\n", f);
		ical_export_uid(f, recur_apoint_tostr(r), export_uid);
		print_date_fmt(f, "DTSTART:", r->start, "%Y%m%dT%H%M%S");
		fprintf(f, "DURATION:P%ldDT%ldH%ldM%ldS\n", d / DAYINSEC,
			(d % DAYINSEC) / HOURINSEC, (d % HOURINSEC) / MININSEC,
			d % MININSEC);
		ical_export_rrule(f, &r->rpt, r->start, 0);
		ical_export_exc(f, &r->rpt.exc, r->start, 0);
		fputs("SUMMARY:", f);
		ical_escape_print(f, r->mesg);
		fputs("\n", f);
		ical_export_note(f, r->note);
		if (r->state & APOINT_NOTIFY)
			ical_export_valarm(f);
		fputs("END:VEVENT\n", f);
	}
	for (i = 0; i < alist.n; i++) {
		struct apoint *a = alist.v[i];
		long d = a->dur;
		fputs("BEGIN:VEVENT\n", f);
		ical_export_uid(f, apoint_tostr(a), export_uid);
		print_date_fmt(f, "DTSTART:", a->start, "%Y%m%dT%H%M%S");
		fprintf(f, "DURATION:P%ldDT%ldH%ldM%ldS\n", d / DAYINSEC,
			(d % DAYINSEC) / HOURINSEC, (d % HOURINSEC) / MININSEC,
			d % MININSEC);
		fputs("SUMMARY:", f);
		ical_escape_print(f, a->mesg);
		fputs("\n", f);
		ical_export_note(f, a->note);
		if (a->state & APOINT_NOTIFY)
			ical_export_valarm(f);
		fputs("END:VEVENT\n", f);
	}
	for (i = 0; i < tlist.n; i++) {
		struct todo *t = tlist.v[i];
		fputs("BEGIN:VTODO\n", f);
		ical_export_uid(f, todo_tostr(t), export_uid);
		fprintf(f, "PRIORITY:%d\n", t->id);
		fputs("SUMMARY:", f);
		ical_escape_print(f, t->mesg);
		fputs("\n", f);
		ical_export_note(f, t->note);
		if (t->completed)
			fputs("STATUS:COMPLETED\n", f);
		fputs("END:VTODO\n", f);
	}
	fputs("END:VCALENDAR\n", f);
}

void pcal_export_data(FILE *f)
{
	int i;
	char buf[64];
	struct tm lt;

	fputs("# calcurse pcal export\n", f);
	fputs("\n# =======\n# options\n# =======\n", f);
	fprintf(f, "opt -A -K -l -m -F %s\n",
		conf.first_day_of_week ? "Monday" : "Sunday");
	fputs("# Display week number (i.e. 1-52) on every Monday\n", f);
	fprintf(f, "all monday in all week %%w\n");
	fputs("\n", f);

	fputs("\n# =============\n# Recur. Events\n# =============\n", f);
	fputs("# (pcal does not support from..until dates specification\n", f);
	for (i = 0; i < relist.n; i++) {
		struct recur_event *r = relist.v[i];
		if (r->rpt.until || r->rpt.freq != 1)
			continue;
