			break;
		case RECUR_WEEKLY:
			strftime(buf, sizeof(buf), "%a %b %d", &lt);
			fprintf(f, "all %.3s on_or_after %s  %s\n", buf, buf + 4,
				r->mesg);
			break;
		case RECUR_MONTHLY:
			strftime(buf, sizeof(buf), "%d", &lt);
			fprintf(f, "day on all %s  %s\n", buf, r->mesg);
			break;
		case RECUR_YEARLY:
			strftime(buf, sizeof(buf), "%b %d", &lt);
			fprintf(f, "%s  %s\n", buf, r->mesg);
			break;
		}
	}

	fputs("\n# ======\n# Events\n# ======\n", f);
	for (i = 0; i < elist.n; i++) {
		struct event *e = elist.v[i];
		localtime_r(&e->day, &lt);
		strftime(buf, sizeof(buf), "%b %d", &lt);
		fprintf(f, "%s  %s\n", buf, e->mesg);
	}
	fputs("\n", f);

	fputs("\n# ==============\n# Recur. Apoints\n# ==============\n", f);
	fputs("# (pcal does not support from..until dates specification\n", f);
	for (i = 0; i < ralist.n; i++) {
		struct recur_apoint *r = ralist.v[i];
		char tbuf[64];
		struct tm et;
		time_t e = r->start + r->dur;
		if (r->rpt.until || r->rpt.freq != 1)
			continue;
		localtime_r(&r->start, &lt);
		localtime_r(&e, &et);
		snprintf(tbuf, sizeof(tbuf), "(%02d:%02d -> %02d:%02d)",
			 lt.tm_hour, lt.tm_min, et.tm_hour, et.tm_min);
		switch (r->rpt.type) {
		case RECUR_DAILY:
			strftime(buf, sizeof(buf), "%b %d", &lt);
