			break;
		case RECUR_MONTHLY:
			strftime(buf, sizeof(buf), "%d", &lt);
			fprintf(f, "day on all %s  %s %s\n", buf, tbuf, r->mesg);
			break;
		case RECUR_YEARLY:
			strftime(buf, sizeof(buf), "%b %d", &lt);
			fprintf(f, "%s  %s %s\n", buf, tbuf, r->mesg);
			break;
		}
	}

	fputs("\n# ============\n# Appointments\n# ============\n", f);
	for (i = 0; i < alist.n; i++) {
		struct apoint *a = alist.v[i];
		struct tm et;
		time_t e = a->start + a->dur;
		localtime_r(&a->start, &lt);
