static void rctx_init(struct rctx *c, time_t start, struct rpt *r)
{
	struct tm lt;
	int i;

	localtime_r(&start, &lt);
	c->r = r;
	c->sy = lt.tm_year + 1900;
	c->sm = lt.tm_mon + 1;
	c->sd = lt.tm_mday;
	c->hh = lt.tm_hour;
	c->mi = lt.tm_min;
	c->ss = lt.tm_sec;
	c->s = days_from_civil(c->sy, c->sm, c->sd);
	c->swd = weekday(c->s);
	c->until = r->until ? civil_of_time(r->until) : LONG_MAX;
	c->nexc = r->exc.n;
	c->exc = c->nexc ? xmalloc(sizeof(long) * c->nexc) : NULL;
	for (i = 0; i < c->nexc; i++)
		c->exc[i] = civil_of_time((time_t)r->exc.v[i]);
	c->check_exc = 1;
}

static void rctx_free(struct rctx *c)
{
	free(c->exc);
}

static int match_mday(struct ilist *l, int y, int m, int d)
{
	int i, dim = days_in_month(y, m);
	for (i = 0; i < l->n; i++) {
		long v = l->v[i];
		if (v > 0 && v == d)
			return 1;
		if (v < 0 && dim + v + 1 == d)
			return 1;
	}
	return 0;
}

static void decode_wday(long w, int *n, int *wd)
{
	if (w >= 0) {
		*n = (int)(w / 7);
		*wd = (int)(w % 7);
	} else {
		*n = -(int)((-w) / 7);
		*wd = (int)((-w) % 7);
	}
}

static long lmod(long a, long b)
{
	long r;
	if (b == 0)
		b = 1;
	r = a % b;
	return r < 0 ? r + b : r;
}

static long freq_of(struct rctx *c)
{
	return c->r->freq;
}

static long week_start(long z)
{
	int fdow = conf.first_day_of_week ? 1 : 0;
	return z - ((weekday(z) - fdow + 7) % 7);
}

static int is_exc(struct rctx *c, long z)
{
	int i;
	if (!c->check_exc)
		return 0;
	for (i = 0; i < c->nexc; i++)
		if (c->exc[i] == z)
			return 1;
	return 0;
}

static void check_wday_month(long w)
{
	if (w < 0 && -w < 7)
		die_at("recur.c", 1267, "illegal BYDAY value");
}

static void check_wday_year(long w)
{
	if (w < 0 && -w < 7)
		die_at("recur.c", 1418, "illegal BYDAY value");
}

/* Period activity of day z. */
static int active(struct rctx *c, long z)
{
	struct rpt *r = c->r;
	int y, m, d;

	civil_from_days(z, &y, &m, &d);
	switch (r->type) {
	case RECUR_DAILY:
		return lmod(z - c->s, freq_of(c)) == 0;
	case RECUR_WEEKLY:
		return lmod((week_start(z) - week_start(c->s)) / 7,
			    freq_of(c)) == 0;
	case RECUR_MONTHLY:
		return lmod((y * 12L + m) - (c->sy * 12L + c->sm),
			    freq_of(c)) == 0;
	case RECUR_YEARLY:
		return lmod((long)y - c->sy, freq_of(c)) == 0;
	}
	return 0;
}

/* Common validity: start, until, exceptions, BYMONTH and period. */
static int valid(struct rctx *c, long x)
{
	int y, m, d;
	if (x < c->s || x > c->until)
		return 0;
	if (is_exc(c, x))
		return 0;
	civil_from_days(x, &y, &m, &d);
	if (c->r->bymonth.n && !ilist_has(&c->r->bymonth, m))
		return 0;
	return active(c, x);
}

static time_t occ_time(struct rctx *c, long z)
{
	int y, m, d;
	struct tm t;

	civil_from_days(z, &y, &m, &d);
	memset(&t, 0, sizeof(t));
	t.tm_year = y - 1900;
	t.tm_mon = m - 1;
	t.tm_mday = d;
	t.tm_hour = c->hh;
	t.tm_min = c->mi;
	t.tm_sec = c->ss;
	t.tm_isdst = -1;
	return mktime(&t);
}

struct query {
	long D;
	time_t day;
	long dur;
};

static int covers(struct rctx *c, struct query *q, long x)
{
	if (x > q->D)
		return 0;
	if (x == q->D)
		return 1;
	return occ_time(c, x) + q->dur > q->day;
}

static int try_day(struct rctx *c, struct query *q, long x, long *res)
{
	if (valid(c, x) && covers(c, q, x)) {
		*res = x;
		return 1;
	}
	return 0;
}

/* nth (n>0) or nth-from-last (n<0) weekday wd in month y/m; 0 if none. */
static long nth_wday_month(int y, int m, int n, int wd)
{
	int dim = days_in_month(y, m), d;
	long first = days_from_civil(y, m, 1);
	d = 1 + ((wd - weekday(first) + 7) % 7);
	if (n > 0) {
		d += (n - 1) * 7;
		if (d > dim)
			return 0;
	} else {
		while (d + 7 <= dim)
			d += 7;
		d -= (-n - 1) * 7;
		if (d < 1)
			return 0;
	}
	return first + d - 1;
}

static long nth_wday_year(int y, int n, int wd)
{
	int diy = is_leap(y) ? 366 : 365, d;
	long first = days_from_civil(y, 1, 1);
	d = (wd - weekday(first) + 7) % 7;
	if (n > 0) {
		d += (n - 1) * 7;
		if (d >= diy)
			return 0;
	} else {
		while (d + 7 < diy)
			d += 7;
		d -= (-n - 1) * 7;
		if (d < 0)
			return 0;
	}
	return first + d;
}

static int wday_limit_month(struct ilist *l, int y, int m, int d, int wd)
{
	int i, n, w, dim = days_in_month(y, m);
	for (i = 0; i < l->n; i++) {
		check_wday_month(l->v[i]);
		decode_wday(l->v[i], &n, &w);
		if (w != wd)
			continue;
		if (n == 0)
			return 1;
		if (n > 0 && (d - 1) / 7 + 1 == n)
			return 1;
		if (n < 0 && (dim - d) / 7 + 1 == -n)
			return 1;
	}
	return 0;
}

static int wday_limit_year(struct ilist *l, int y, int yday0, int wd)
{
	int i, n, w, diy = is_leap(y) ? 366 : 365;
	for (i = 0; i < l->n; i++) {
		check_wday_year(l->v[i]);
		decode_wday(l->v[i], &n, &w);
		if (w != wd)
			continue;
		if (n == 0)
			return 1;
		if (n > 0 && yday0 / 7 == n)
			return 1;
		if (n < 0 && (diy - 1 - yday0) / 7 + 2 == -n)
			return 1;
	}
	return 0;
}

static long latest_wday(long t, int wd)
{
	return t - lmod(weekday(t) - wd, 7);
}

static int prev_month(int *y, int *m)
{
	if (--(*m) < 1) {
		*m = 12;
		(*y)--;
	}
	return 1;
}

/* Find an occurrence covering day q->D.  Returns 1 and the day in *res. */
static int find_occ(struct rctx *c, struct query *q, long *res)
{
	struct rpt *r = c->r;
	long D = q->D, x;
	int Dy, Dm, Dd, i, k;

	if (D < c->s)
		return 0;
	civil_from_days(D, &Dy, &Dm, &Dd);

	switch (r->type) {
	case RECUR_DAILY: {
		int y, m, d;
		x = D - lmod(D - c->s, freq_of(c));
		civil_from_days(x, &y, &m, &d);
		if (r->bymonthday.n && !match_mday(&r->bymonthday, y, m, d))
			return 0;
		if (r->bywday.n && !ilist_has(&r->bywday, weekday(x)))
			return 0;
		return try_day(c, q, x, res);
	}
	case RECUR_WEEKLY:
		if (!r->bywday.n) {
			x = D - lmod(D - c->s, 7 * freq_of(c));
			return try_day(c, q, x, res);
		}
		for (i = 0; i < r->bywday.n; i++) {
			long w = r->bywday.v[i];
			if (w < 0 || w > 6)
				continue;
			x = latest_wday(D, (int)w);
			if (try_day(c, q, x, res))
				return 1;
		}
		return 0;
	case RECUR_MONTHLY:
		if (r->bymonthday.n) {
			for (i = 0; i < r->bymonthday.n; i++) {
				long v = r->bymonthday.v[i];
				int dim = days_in_month(Dy, Dm), dn, y = Dy,
				    m = Dm;
				dn = v > 0 ? (int)v : dim + (int)v + 1;
				if (dn < 1)
					continue;
				if (dn > dim || dn > Dd) {
					prev_month(&y, &m);
					if (dn > days_in_month(y, m))
						continue;
				}
				x = days_from_civil(y, m, dn);
				if (r->bywday.n &&
				    !wday_limit_month(&r->bywday, y, m, dn,
						      weekday(x)))
					continue;
				if (try_day(c, q, x, res))
					return 1;
			}
			return 0;
		}
		if (r->bywday.n) {
			long t = D;
			for (i = 0; i < r->bywday.n; i++) {
				int n, wd, ty, tm, td;
				check_wday_month(r->bywday.v[i]);
				decode_wday(r->bywday.v[i], &n, &wd);
				if (n == 0) {
					x = latest_wday(t, wd);
					if (try_day(c, q, x, res))
						return 1;
					continue;
				}
				civil_from_days(t, &ty, &tm, &td);
				x = nth_wday_month(ty, tm, n, wd);
				if (!x)
					continue;
				if (x <= D && try_day(c, q, x, res))
					return 1;
				if (x < D)
					t = x;
			}
			return 0;
		}
		/* simple monthly: latest existing day in an active month */
		{
			int y = Dy, m = Dm;
			for (k = 0; k < 24; k++) {
				if (lmod((y * 12L + m) - (c->sy * 12L + c->sm),
					 freq_of(c)) == 0 &&
				    c->sd <= days_in_month(y, m)) {
					x = days_from_civil(y, m, c->sd);
					if (x <= D)
						return try_day(c, q, x, res);
				}
				prev_month(&y, &m);
			}
			return 0;
		}
	case RECUR_YEARLY:
		if (r->bymonthday.n) {
			int nm = r->bymonth.n ? r->bymonth.n : 1;
			for (k = 0; k < nm; k++) {
				int m = r->bymonth.n ? (int)r->bymonth.v[k] :
					c->sm;
				if (m < 1 || m > 12)
					continue;
				for (i = 0; i < r->bymonthday.n; i++) {
					long v = r->bymonthday.v[i];
					int y = Dy, dn, dim;
					dim = days_in_month(y, m);
					dn = v > 0 ? (int)v : dim + (int)v + 1;
					if (dn < 1)
						continue;
					if (dn > dim ||
					    days_from_civil(y, m, dn) > D) {
						y--;
						if (dn > days_in_month(y, m))
							continue;
					}
					y = y - (int)lmod(y - c->sy, freq_of(c));
					if (dn > days_in_month(y, m))
						continue;
					x = days_from_civil(y, m, dn);
					if (r->bywday.n) {
						int ok;
						if (r->bymonth.n)
							ok = wday_limit_month(
								&r->bywday, y, m, dn,
								weekday(x));
						else
							ok = wday_limit_year(
								&r->bywday, y,
								(int)(x - days_from_civil(y, 1, 1)),
								weekday(x));
						if (!ok)
							continue;
					}
					if (try_day(c, q, x, res))
						return 1;
				}
			}
			return 0;
		}
		if (r->bywday.n) {
			if (lmod((long)Dy - c->sy, freq_of(c)) != 0)
				return 0;
			for (i = 0; i < r->bywday.n; i++) {
				int n, wd;
				check_wday_year(r->bywday.v[i]);
				decode_wday(r->bywday.v[i], &n, &wd);
				if (n == 0) {
					x = latest_wday(D, wd);
					if (try_day(c, q, x, res))
						return 1;
					continue;
				}
				if (r->bymonth.n) {
					for (k = 0; k < r->bymonth.n; k++) {
						int m = (int)r->bymonth.v[k];
						if (m < 1 || m > 12)
							continue;
						x = nth_wday_month(Dy, m, n, wd);
						if (x && x <= D &&
						    try_day(c, q, x, res))
							return 1;
					}
				} else {
					x = nth_wday_year(Dy, n, wd);
					if (x && x <= D && try_day(c, q, x, res))
						return 1;
				}
			}
			return 0;
		}
		{
			int nm = r->bymonth.n ? r->bymonth.n : 1;
			for (k = 0; k < nm; k++) {
				int m = r->bymonth.n ? (int)r->bymonth.v[k] :
					c->sm;
				int y = Dy;
				if (m < 1 || m > 12)
					continue;
				if (c->sd > days_in_month(y, m) ||
				    days_from_civil(y, m, c->sd) > D)
					y--;
				y = y - (int)lmod(y - c->sy, freq_of(c));
				if (c->sd > days_in_month(y, m))
					continue;
				x = days_from_civil(y, m, c->sd);
				if (try_day(c, q, x, res))
					return 1;
			}
			return 0;
		}
	}
	return 0;
}

/* Is day z an occurrence day of the rule (exceptions ignored)? */
static int candidate(struct rctx *c, long z)
{
	struct query q;
	long res;
	int save = c->check_exc, ret;

	q.D = z;
	q.day = 0;
	q.dur = 0;
	c->check_exc = 0;
	ret = find_occ(c, &q, &res) && res == z;
	c->check_exc = save;
	return ret;
}

int recur_candidate(time_t start, struct rpt *rpt, time_t day)
{
	struct rctx c;
	int ret;
	rctx_init(&c, start, rpt);
	ret = candidate(&c, civil_of_time(day));
	rctx_free(&c);
	return ret;
}

int recur_item_find_occurrence(time_t start, long dur, struct rpt *rpt,
			       time_t day, time_t *occurrence)
{
	struct rctx c;
	struct query q;
	long res;
	int ret = 0;

	rctx_init(&c, start, rpt);
	q.D = civil_of_time(day);
	q.day = day;
	q.dur = dur;
	if (find_occ(&c, &q, &res)) {
		if (occurrence)
			*occurrence = occ_time(&c, res);
		ret = 1;
	}
	rctx_free(&c);
	return ret;
}

int recur_apoint_find_occurrence(struct recur_apoint *r, time_t day,
				 time_t *occurrence)
{
	return recur_item_find_occurrence(r->start, r->dur, &r->rpt, day,
					  occurrence);
}

int recur_event_find_occurrence(struct recur_event *r, time_t day,
				time_t *occurrence)
{
	return recur_item_find_occurrence(r->day, 0, &r->rpt, day,
					  occurrence);
}

#define SCAN_LIMIT (400L * 366L)

int recur_next_occurrence(time_t start, struct rpt *rpt, time_t day,
			  time_t *next, int ignore_until, int skip_exc)
{
	struct rctx c;
	long z, lim;
	int ret = 0;

	rctx_init(&c, start, rpt);
	z = civil_of_time(day) + 1;
	if (z < c.s)
		z = c.s;
	for (lim = 0; lim < SCAN_LIMIT; lim++, z++) {
		if (!ignore_until && z > c.until)
			break;
		if (!candidate(&c, z))
			continue;
		if (skip_exc && is_exc(&c, z))
			continue;
		*next = occ_time(&c, z);
		ret = 1;
		break;
	}
	rctx_free(&c);
	return ret;
}

/*
 * Find the n-th occurrence (1-based).  The start counts as the first
 * occurrence; later exceptions are skipped.
 */
int recur_nth_occurrence(time_t start, struct rpt *rpt, int n, time_t *nth)
{
	struct rctx c;
	long z, lim;
	int k = 1, ret = 0;

	rctx_init(&c, start, rpt);
	c.until = LONG_MAX;
	if (n <= 1) {
		*nth = occ_time(&c, c.s);
		rctx_free(&c);
		return 1;
	}
	z = c.s + 1;
	for (lim = 0; lim < SCAN_LIMIT * 4; lim++, z++) {
		if (!candidate(&c, z) || is_exc(&c, z))
			continue;
		if (++k == n) {
			*nth = occ_time(&c, z);
			ret = 1;
			break;
		}
	}
	rctx_free(&c);
	return ret;
}

long recur_apoint_end(struct recur_apoint *r)
{
	return r->start + r->dur;
}
