    if random.random() < 0.2: props.append(random.choice(['EXDATE:', 'EXDATE;VALUE=DATE:', 'EXDATE ']) + random.choice([val_dt(), val_date(), 'x']))
    if random.random() < 0.2: props += ['BEGIN:VALARM', 'TRIGGER:-PT5M', 'SUMMARY:alarm', 'DURATION:PT1H', 'END:VALARM']
    if random.random() < 0.2: props.append(random.choice(['STATUS:CONFIRMED', 'UID:abc', 'X-FOO:bar', 'TRANSP:OPAQUE', 'CATEGORIES:a,b']))
    random.shuffle(props)
    L += props
    if random.random() < 0.97: L.append('END:VEVENT')
    return L
def vtodo():
    L = ['BEGIN:VTODO']
    props = []
    if random.random() < 0.9: props.append(prop('SUMMARY') + random.choice(TEXTS))
    if random.random() < 0.6: props.append(random.choice(['PRIORITY:', 'PRIORITY ', 'PRIORITY;X=1:', 'priority:']) + random.choice(['1', '5', '9', '0', '10', '-1', 'x', '', ' 3']))
    if random.random() < 0.3: props.append(random.choice(['STATUS:COMPLETED', 'STATUS:NEEDS-ACTION', 'status:completed', 'STATUS;X=1:COMPLETED']))
    for _ in range(random.randint(0, 2)): props.append(prop('DESCRIPTION') + random.choice(TEXTS))
    for _ in range(random.randint(0, 1)): props.append(prop('LOCATION') + random.choice(TEXTS))
    for _ in range(random.randint(0, 2)): props.append(prop('COMMENT') + random.choice(TEXTS))
    if random.random() < 0.2: props += ['BEGIN:VALARM', 'TRIGGER:-PT5M', 'END:VALARM']
    random.shuffle(props)
    L += props
    if random.random() < 0.97: L.append('END:VTODO')
    return L
fails = 0
for it in range(N):
    lines = ['BEGIN:VCALENDAR', 'VERSION:2.0']
    for _ in range(random.randint(1, 6)):
        lines += vevent() if random.random() < 0.6 else vtodo()
