    lines.append('END:VCALENDAR')
    ics = '\n'.join(lines) + '\n'
    if random.random() < 0.2: ics = ics.replace('\n', '\r\n')
    o = run_one(ORIG, {'in.ics': ics}, ['-D', '@D', '-i', '@B/in.ics', '--dump-imported'], '/tmp/h/run_chk%d' % os.getpid(), timeout=5)
    if o[2] == -999 or o[2] < 0:
