    ok = compare({'in.ics': ics}, ['-D', '@D', '-i', '@B/in.ics', '--dump-imported'], show=False, timeout=5)
    if not ok:
        fails += 1
        open('/tmp/h/fail3_%d_%s.ics' % (it, sys.argv[1]), 'w').write(ics)
        print('FAIL', it)
print('fails', fails)
EOF
