actions.command:
cat > /workspace/src/ui.c <<'EOF'
/*
 * Interactive (curses) user interface.
 */
#include "calcurse.h"
#include <curses.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include "keys.h"

enum { PANEL_CAL, PANEL_APP, PANEL_TODO, NPANELS };

#define CALHEIGHT 12
#define SBARMINWIDTH 34

static WINDOW *win[NPANELS], *win_notify, *win_status;
static int sel_panel = PANEL_CAL;
static time_t sel_day;		/* midnight of the selected day */
static int app_sel = 0, todo_sel = 0;
static int has_colors_ok = 0;
static int modified = 0;

static void ui_load_data(void)
{
	plist_clear(&alist);
	plist_clear(&elist);
	plist_clear(&ralist);
	plist_clear(&relist);
	plist_clear(&tlist);
	run_hook("pre-load");
	io_load_app(NULL);
	io_load_todo(NULL);
	run_hook("post-load");
}

static void ui_save_data(void)
{
	if (read_only)
		return;
	run_hook("pre-save");
	io_save_apts(path_apts);
	io_save_todo(path_todo);
	run_hook("post-save");
	modified = 0;
}

static void attr_on(WINDOW *w, int pair, int bold)
{
	if (has_colors_ok && pair)
		wattron(w, COLOR_PAIR(pair));
	if (bold)
		wattron(w, A_BOLD);
}

static void attr_off(WINDOW *w, int pair, int bold)
{
	if (has_colors_ok && pair)
		wattroff(w, COLOR_PAIR(pair));
	if (bold)
		wattroff(w, A_BOLD);
}

static void draw_frame(WINDOW *w, const char *title, int selected)
{
	int width = getmaxx(w);

	if (selected)
		attr_on(w, 1, 0);
	box(w, 0, 0);
	if (selected)
		attr_off(w, 1, 0);
	attr_on(w, 1, 0);
	mvwaddstr(w, 1, (width - (int)strlen(title)) / 2, title);
	attr_off(w, 1, 0);
	if (selected)
		attr_on(w, 1, 0);
	mvwaddch(w, 2, 0, ACS_LTEE);
	mvwhline(w, 2, 1, ACS_HLINE, width - 2);
	mvwaddch(w, 2, width - 1, ACS_RTEE);
	if (selected)
		attr_off(w, 1, 0);
}

static long day_civil(time_t t, int *y, int *m, int *d, int *wd)
{
	struct tm lt;
	localtime_r(&t, &lt);
	if (y)
		*y = lt.tm_year + 1900;
	if (m)
		*m = lt.tm_mon + 1;
	if (d)
		*d = lt.tm_mday;
	if (wd)
		*wd = lt.tm_wday;
	return 0;
}

static int day_has_items(time_t day)
{
	day_store_items(day, 1);
	return day_item_count();
}

static void draw_calendar(void)
{
	WINDOW *w = win[PANEL_CAL];
	int width = getmaxx(w);
	int y, m, d, wd, i, row, col;
	char buf[64];
	struct tm lt;
	time_t first, t, today = get_today();
	static const char *dn[] = { "Sun", "Mon", "Tue", "Wed", "Thu", "Fri",
		"Sat" };
	int fdow = conf.first_day_of_week ? 1 : 0;

	werase(w);
	draw_frame(w, "Calendar", sel_panel == PANEL_CAL);

	localtime_r(&sel_day, &lt);
	snprintf(buf, sizeof(buf), "(#%d)", lt.tm_yday + 1);
	attr_on(w, 1, 0);
	mvwaddstr(w, 2, width - 2 - (int)strlen(buf), buf);
	attr_off(w, 1, 0);

	strftime(buf, sizeof(buf), "%B %Y", &lt);
	attr_on(w, 1, 0);
	mvwaddstr(w, 3, (width - (int)strlen(buf)) / 2, buf);
	for (i = 0; i < 7; i++)
		mvwaddstr(w, 4, 5 + 4 * i, dn[(i + fdow) % 7]);
	attr_off(w, 1, 0);

	day_civil(sel_day, &y, &m, &d, &wd);
	first = date2sec(y, m, 1, 0, 0);
	day_civil(first, NULL, NULL, NULL, &wd);
	/* start of the first displayed week */
	t = date_sec_change(first, 0, -((wd - fdow + 7) % 7));
	for (row = 0; row < 6; row++) {
		time_t wstart = t;
		int cy, cm, cd;
		struct tm wt;
		int in_month = 0;

		for (col = 0; col < 7; col++) {
			time_t x = date_sec_change(wstart, 0, col);
			day_civil(x, &cy, &cm, &cd, NULL);
			if (cm == m && cy == y)
				in_month = 1;
		}
		if (!in_month)
			break;
		localtime_r(&wstart, &wt);
		{
			time_t thu = date_sec_change(wstart, 0, fdow ? 3 : 4);
			struct tm tt;
			localtime_r(&thu, &tt);
			strftime(buf, sizeof(buf), fdow ? "%V" : "%U", fdow ?
				 &tt : &wt);
		}
		attr_on(w, 1, 0);
		mvwprintw(w, 5 + row, 2, "%2d", atoi(buf));
		attr_off(w, 1, 0);
		for (col = 0; col < 7; col++) {
			time_t x = date_sec_change(wstart, 0, col);
			int xc = 6 + 4 * col;
			day_civil(x, &cy, &cm, &cd, NULL);
			if (x == sel_day) {
				attr_on(w, 1, 1);
				mvwaddch(w, 5 + row, xc - 1, '[');
				attr_off(w, 1, 1);
				attr_on(w, x == today ? 3 : 0, 0);
				mvwprintw(w, 5 + row, xc, "%2d", cd);
				attr_off(w, x == today ? 3 : 0, 0);
				attr_on(w, 1, 1);
				mvwaddch(w, 5 + row, xc + 2, ']');
				attr_off(w, 1, 1);
			} else {
				int pair = 0;
				if (x == today)
					pair = 3;
				else if (day_has_items(x))
					pair = 2;
				attr_on(w, pair, 0);
				mvwprintw(w, 5 + row, xc, "%2d", cd);
				attr_off(w, pair, 0);
			}
		}
		t = date_sec_change(wstart, 0, 7);
	}
	wnoutrefresh(w);
}

static void hline_sep(WINDOW *w, int row)
{
	int width = getmaxx(w);
	mvwaddch(w, row, 0, ACS_LTEE);
	mvwhline(w, row, 1, ACS_HLINE, width - 2);
	mvwaddch(w, row, width - 1, ACS_RTEE);
}

static void print_clipped(WINDOW *w, int row, int col, const char *s)
{
	int width = getmaxx(w);
	int max = width - 1 - col;
	if (max <= 0)
		return;
	mvwaddnstr(w, row, col, s, max);
}

static void draw_appointments(void)
{
	WINDOW *w = win[PANEL_APP];
	int width = getmaxx(w), height = getmaxy(w);
	int row = 3, i, n, first_item = 1, item_idx = 0;
	time_t day = sel_day;
	char buf[BUFSIZ_];
	struct tm lt;

	werase(w);
	draw_frame(w, "Appointments", sel_panel == PANEL_APP);

	while (row < height - 1) {
		int nev = 0, napt = 0;

		localtime_r(&day, &lt);
		strftime(buf, sizeof(buf), conf.day_heading, &lt);
		attr_on(w, 1, 1);
		if (conf.heading_pos == 0)
			mvwaddstr(w, row, 1, buf);
		else if (conf.heading_pos == 1)
			mvwaddstr(w, row, (width - (int)strlen(buf)) / 2, buf);
		else
			mvwaddstr(w, row, width - (int)strlen(buf) - 2, buf);
		attr_off(w, 1, 1);
		row++;

		day_store_items(day, 1);
		n = day_item_count();
		for (i = 0; i < n; i++) {
			struct day_item *it = day_get_item(i);
			if (it->type == DI_EVNT || it->type == DI_RECUR_EVNT)
				nev++;
			else
				napt++;
		}
		if (n == 0) {
			if (row < height - 1)
				print_clipped(w, row, 4, conf.empty_day);
			row++;
			row++;
		}
		for (i = 0; i < n && row < height - 1; i++) {
			struct day_item *it = day_get_item(i);
			int hl = (sel_panel == PANEL_APP && first_item &&
				  item_idx == app_sel);
			if (it->type == DI_EVNT || it->type == DI_RECUR_EVNT) {
				const char *mesg = it->type == DI_EVNT ?
					((struct event *)it->item)->mesg :
					((struct recur_event *)it->item)->mesg;
				if (hl)
					wattron(w, A_REVERSE);
				print_clipped(w, row, 4, mesg);
				if (hl)
					wattroff(w, A_REVERSE);
				row++;
				if (i == nev - 1)
					row++;
			} else {
				time_t s = it->start, e;
				const char *mesg;
				long dur;
				char state;
				char sb[16], eb[16], line[64];
				struct tm st, et;
				int recur = it->type == DI_RECUR_APPT;

				if (recur) {
					struct recur_apoint *r = it->item;
					dur = r->dur;
					mesg = r->mesg;
					state = r->state;
				} else {
					struct apoint *a = it->item;
					dur = a->dur;
					mesg = a->mesg;
					state = a->state;
				}
				e = s + dur;
				localtime_r(&s, &st);
				localtime_r(&e, &et);
				if (s < day)
					strcpy(sb, "..:..");
				else
					strftime(sb, sizeof(sb), "%H:%M", &st);
				if (e > date_sec_change(day, 0, 1))
					strcpy(eb, "..:..");
				else
					strftime(eb, sizeof(eb), "%H:%M", &et);
				snprintf(line, sizeof(line), " %c%c%s -> %s",
					 recur ? '*' : '-',
					 (state & APOINT_NOTIFY) ? '!' : ' ', sb,
					 eb);
				if (hl)
					wattron(w, A_REVERSE);
				print_clipped(w, row, 1, line);
				row++;
				if (row < height - 1)
					print_clipped(w, row, 4, mesg);
				if (hl)
					wattroff(w, A_REVERSE);
				row += 2;
			}
			item_idx++;
		}
		first_item = 0;
		row++;
		if (row < height - 1)
			hline_sep(w, row);
		row++;
		day = date_sec_change(day, 0, 1);
		if (!conf.multiple_days)
			break;
	}
	/* restore the border overwritten by separators at the bottom */
	box(w, 0, 0);
	if (sel_panel == PANEL_APP) {
		attr_on(w, 1, 0);
		box(w, 0, 0);
		attr_off(w, 1, 0);
	}
	{
		/* redraw title area after box */
		attr_on(w, 1, 0);
		mvwaddstr(w, 1, (width - 12) / 2, "Appointments");
		attr_off(w, 1, 0);
	}
	wnoutrefresh(w);
}

static void draw_todo(void)
{
	WINDOW *w = win[PANEL_TODO];
	int height = getmaxy(w);
	int i, row = 3;
	char buf[BUFSIZ_];

	werase(w);
	draw_frame(w, "TODO", sel_panel == PANEL_TODO);
	for (i = 0; i < tlist.n && row < height - 1; i++, row++) {
		struct todo *t = tlist.v[i];
		if (conf.todo_view && t->completed) {
			row--;
			continue;
		}
		if (t->completed)
			snprintf(buf, sizeof(buf), "X. %s", t->mesg);
		else
			snprintf(buf, sizeof(buf), "%d. %s", t->id, t->mesg);
		if (sel_panel == PANEL_TODO && i == todo_sel)
			wattron(w, A_REVERSE);
		print_clipped(w, row, 1, buf);
		if (sel_panel == PANEL_TODO && i == todo_sel)
			wattroff(w, A_REVERSE);
	}
	wnoutrefresh(w);
}

static void draw_notify(void)
{
	WINDOW *w = win_notify;
	int width = getmaxx(w);
	time_t now = time(NULL);
	struct tm lt;
	char d[64], t[64], buf[BUFSIZ_];
	const char *fname;
	time_t best = now + DAYINSEC;
	const char *txt = NULL;
	int i;

	werase(w);
	mvwhline(w, 0, 0, ACS_HLINE, width);
	localtime_r(&now, &lt);
	strftime(d, sizeof(d), conf.notify_date, &lt);
	strftime(t, sizeof(t), conf.notify_time, &lt);
	snprintf(buf, sizeof(buf), "[ %s | %s ]", d, t);
	mvwaddstr(w, 0, 3, buf);
	fname = strrchr(path_apts, '/');
	fname = fname ? fname + 1 : path_apts;
	snprintf(buf, sizeof(buf), "(%s)", fname);
	mvwaddstr(w, 0, 3 + (int)strlen(d) + (int)strlen(t) + 9, buf);

	for (i = 0; i < alist.n; i++) {
		struct apoint *a = alist.v[i];
		if (a->start > now && a->start < best) {
			best = a->start;
			txt = a->mesg;
		}
	}
	for (i = 0; i < ralist.n; i++) {
		struct recur_apoint *r = ralist.v[i];
		time_t day = get_today(), occ;
		int k;
		for (k = 0; k < 2; k++, day = date_sec_change(day, 0, 1)) {
			if (recur_apoint_find_occurrence(r, day, &occ) &&
			    occ > now && occ < best) {
				best = occ;
				txt = r->mesg;
			}
		}
	}
	if (txt) {
		long left = (long)(best - now);
		int hh = (int)(left / HOURINSEC);
		int mm = (int)((left % HOURINSEC) / MININSEC);
		int x = 3 + (int)strlen(d) + (int)strlen(t) + 9 +
			(int)strlen(fname) + 2 + 3;
		int avail = width - x - 13;
		snprintf(buf, sizeof(buf), "> %02d:%02d :: %s <", hh, mm,
			 avail >= (int)strlen(txt) ? txt : "...");
		mvwaddstr(w, 0, x, buf);
	}
	wnoutrefresh(w);
}

struct cmd {
	const char *key;
	const char *label;
};

static void draw_status(void)
{
	static const struct cmd cal[2][6] = {
		{ { "?", "Help" }, { "s", "Save" }, { "TAB", "Chg Win" },
		  { "^N", "Nxt View" }, { "k", "Up" }, { "h", "Left" } },
		{ { "q", "Quit" }, { "R", "Reload" }, { "...", "Prev Win" },
		  { "^P", "Prv View" }, { "j", "Down" }, { "o", "OtherCmd" } }
	};
	static const struct cmd app[2][6] = {
		{ { "?", "Help" }, { "s", "Save" }, { "TAB", "Chg Win" },
		  { "i", "Import" }, { "a", "Add Item" }, { "e", "Edit Itm" } },
		{ { "q", "Quit" }, { "R", "Reload" }, { "...", "Prev Win" },
		  { "x", "Export" }, { "d", "Del Item" }, { "o", "OtherCmd" } }
	};
	static const struct cmd todo[2][6] = {
		{ { "?", "Help" }, { "s", "Save" }, { "TAB", "Chg Win" },
		  { "^N", "Nxt View" }, { "i", "Import" }, { "a", "Add Item" } },
		{ { "q", "Quit" }, { "R", "Reload" }, { "...", "Prev Win" },
		  { "^P", "Prv View" }, { "x", "Export" }, { "o", "OtherCmd" } }
	};
	const struct cmd (*c)[6] = sel_panel == PANEL_CAL ? cal :
				   sel_panel == PANEL_APP ? app : todo;
	WINDOW *w = win_status;
	int width = getmaxx(w), slot = width / 6, r, i;

	werase(w);
	for (r = 0; r < 2; r++) {
		for (i = 0; i < 6; i++) {
			int x = i * slot;
			int kl = (int)strlen(c[r][i].key);
			attr_on(w, 1, 0);
			mvwaddstr(w, r, x + 3 - kl, c[r][i].key);
			attr_off(w, 1, 0);
			mvwaddstr(w, r, x + 4, c[r][i].label);
		}
	}
	wnoutrefresh(w);
}

static void layout(void)
{
	int sbar, napp;
	int i;

	for (i = 0; i < NPANELS; i++)
		if (win[i])
			delwin(win[i]);
	if (win_notify)
		delwin(win_notify);
	if (win_status)
		delwin(win_status);

	sbar = COLS * conf.sidebar_width / 100;
	if (sbar < SBARMINWIDTH)
		sbar = SBARMINWIDTH;
	napp = COLS - sbar;
	if (napp < 1)
		napp = 1;
	win[PANEL_APP] = newwin(LINES - 3, napp, 0, 0);
	win[PANEL_CAL] = newwin(CALHEIGHT, sbar, 0, napp);
	win[PANEL_TODO] = newwin(LINES - 3 - CALHEIGHT, sbar, CALHEIGHT,
				 napp);
	win_notify = newwin(1, COLS, LINES - 3, 0);
	win_status = newwin(2, COLS, LINES - 2, 0);
}

static void redraw(void)
{
	draw_appointments();
	draw_calendar();
	draw_todo();
	draw_notify();
	draw_status();
	doupdate();
}

static int confirm(const char *msg)
{
	int ch;
	werase(win_status);
	mvwaddstr(win_status, 0, 0, msg);
	mvwaddstr(win_status, 1, 0, "[y/n]");
	wrefresh(win_status);
	for (;;) {
		ch = wgetch(win_status);
		if (ch == ERR)
			continue;
		return ch == 'y' || ch == 'Y';
	}
}

static void move_day(int months, int days)
{
	sel_day = date_sec_change(sel_day, months, days);
	app_sel = 0;
}

static void cleanup(void)
{
	endwin();
	if (!read_only)
		unlink(path_cpid);
	else
		unlink(path_cpid);
}

int ui_main(void)
{
	unsigned cpid;
	FILE *fp;
	int ch, quit = 0;

	io_check_dir(path_ddir);
	io_check_dir(path_cdir);
	io_check_dir(path_notes);
	io_check_dir(path_hooks);
	io_check_file(path_apts);
	io_check_file(path_todo);
	io_check_file(path_conf);
	if (!read_only && access(path_keys, F_OK) != 0) {
		fp = fopen(path_keys, "w");
		if (fp) {
			fputs(default_keys, fp);
			fclose(fp);
		}
	}

	cpid = io_get_pid(path_cpid);
	if (cpid && kill((pid_t)cpid, 0) == 0) {
		fprintf(stderr,
			"\nWARNING: it seems that another calcurse instance is already running.\n"
			"If this is not the case, please remove the following lock file: \n"
			"\"%s\"\n"
			"and restart calcurse.\n",
			path_cpid);
		exit(EXIT_FAILURE);
	}
	fp = fopen(path_cpid, "w");
	if (!fp) {
		fprintf(stderr, "io.c: 1509: FATAL ERROR: could not create %s: %s\n",
			path_cpid, strerror(errno));
		exit(EXIT_FAILURE);
	}
	fprintf(fp, "%d\n", (int)getpid());
	fclose(fp);

	initscr();
	cbreak();
	noecho();
	nonl();
	keypad(stdscr, TRUE);
	curs_set(0);
	if (has_colors()) {
		start_color();
		use_default_colors();
		init_pair(1, COLOR_RED, -1);
		init_pair(2, COLOR_GREEN, -1);
		init_pair(3, COLOR_YELLOW, -1);
		init_pair(4, COLOR_CYAN, -1);
		has_colors_ok = 1;
	}
	refresh();

	ui_load_data();
	sel_day = get_today();
	sel_panel = conf.default_panel == 1 ? PANEL_APP :
		    conf.default_panel == 2 ? PANEL_TODO : PANEL_CAL;
	layout();

	while (!quit) {
		redraw();
		wtimeout(win_status, 1000);
		keypad(win_status, TRUE);
		ch = wgetch(win_status);
		switch (ch) {
		case ERR:
			break;
		case KEY_RESIZE:
			layout();
			break;
		case '\t':
			sel_panel = (sel_panel + 1) % NPANELS;
			break;
		case KEY_BTAB:
			sel_panel = (sel_panel + NPANELS - 1) % NPANELS;
			break;
		case 'q':
		case 'Q':
			if (!conf.confirm_quit ||
			    confirm("Do you really want to quit?"))
				quit = 1;
			break;
		case 's':
		case 'S':
		case 19: /* ^S */
			ui_save_data();
			break;
		case 'R':
			ui_load_data();
			break;
		case 18: /* ^R */
			clearok(curscr, TRUE);
			break;
		case 7: /* ^G */
			sel_day = get_today();
			break;
		case 'T':
		case 8:
			move_day(0, -1);
			break;
		case 't':
		case 12:
			move_day(0, 1);
			break;
		case 'W':
		case 11:
			move_day(0, -7);
			break;
		case 'w':
			move_day(0, 7);
			break;
		case 'M':
			move_day(-1, 0);
			break;
		case 'm':
			move_day(1, 0);
			break;
		case 'Y':
			move_day(-12, 0);
			break;
		case 'y':
			move_day(12, 0);
			break;
		case 'h':
		case 'H':
		case KEY_LEFT:
			if (sel_panel == PANEL_CAL)
				move_day(0, -1);
			break;
		case 'l':
		case 'L':
		case KEY_RIGHT:
			if (sel_panel == PANEL_CAL)
				move_day(0, 1);
			break;
		case 'k':
		case 'K':
		case KEY_UP:
			if (sel_panel == PANEL_CAL)
				move_day(0, -7);
			else if (sel_panel == PANEL_APP && app_sel > 0)
				app_sel--;
			else if (sel_panel == PANEL_TODO && todo_sel > 0)
				todo_sel--;
			break;
		case 'j':
		case 'J':
		case KEY_DOWN:
			if (sel_panel == PANEL_CAL) {
				move_day(0, 7);
			} else if (sel_panel == PANEL_APP) {
				day_store_items(sel_day, 1);
				if (app_sel + 1 < day_item_count())
					app_sel++;
			} else if (sel_panel == PANEL_TODO &&
				   todo_sel + 1 < tlist.n) {
				todo_sel++;
			}
			break;
		default:
			break;
		}
	}
	if (modified && conf.auto_save)
		ui_save_data();
	cleanup();
	return EXIT_SUCCESS;
}
