/* Simple line editor in the status window.  Returns 1 on Enter, 0 on ESC. */
static int getstring(const char *prompt, char *buf, size_t n)
{
	size_t len = strlen(buf);
	int ch;

	for (;;) {
		werase(win_status);
		ui_aon(win_status, 1, 0);
		mvwaddstr(win_status, 0, 0, prompt);
		ui_aoff(win_status, 1, 0);
		mvwaddstr(win_status, 1, 0, buf);
		wmove(win_status, 1, (int)len);
		curs_set(1);
		wrefresh(win_status);
		wtimeout(win_status, -1);
		ch = wgetch(win_status);
		curs_set(0);
		if (ch == '\n' || ch == '\r' || ch == KEY_ENTER)
			return 1;
		if (ch == 27)
			return 0;
		if (ch == KEY_BACKSPACE || ch == 127 || ch == 8) {
			if (len > 0)
				buf[--len] = '\0';
			continue;
		}
		if (ch == 21) {	/* ^U */
			len = 0;
			buf[0] = '\0';
			continue;
		}
		if (ch >= 32 && ch < 256 && len + 1 < n) {
			buf[len++] = (char)ch;
			buf[len] = '\0';
		}
	}
}

static int getkey_prompt(const char *l1, const char *l2)
{
	int ch;
	werase(win_status);
	ui_aon(win_status, 1, 0);
	mvwaddstr(win_status, 0, 0, l1);
	mvwaddstr(win_status, 1, 0, l2);
	ui_aoff(win_status, 1, 0);
	wrefresh(win_status);
	wtimeout(win_status, -1);
	do {
		ch = wgetch(win_status);
	} while (ch == ERR);
	return ch;
}

/* Parse an end time specification relative to start. */
static int parse_end(const char *s, time_t start, time_t *end)
{
	int h, m;
	const char *p = s;

	while (*p == ' ')
		p++;
	if (*p == '+' || *p == '-') {
		long mins = 0, sign = *p == '-' ? -1 : 1;
		int hh, mm;
		p++;
		if (parse_time(p, &hh, &mm)) {
			mins = hh * 60 + mm;
		} else {
			char *e;
			mins = strtol(p, &e, 10);
			if (*e == 'h' || *e == 'H') {
				long hrs = mins;
				mins = hrs * 60;
				if (*(e + 1)) {
					char *e2;
					mins += strtol(e + 1, &e2, 10);
					if (*e2 == 'm' || *e2 == 'M')
						e2++;
					if (*e2)
						return 0;
				}
			} else if (*e == 'm' || *e == 'M') {
				if (*(e + 1))
					return 0;
			} else if (*e || e == p) {
				return 0;
			}
		}
		*end = start + sign * mins * 60;
		return *end >= start;
	}
	if (parse_time(p, &h, &m)) {
		time_t e = update_time_in_date(start, h, m);
		if (e < start)
			e = date_sec_change(e, 0, 1);
		*end = e;
		return 1;
	}
	return 0;
}

static void ui_add_appointment(void)
{
	char buf[BUFSIZ_] = "", ebuf[BUFSIZ_] = "", desc[BUFSIZ_] = "";
	int h, m;
	time_t start, end;

	for (;;) {
		buf[0] = '\0';
		if (!getstring("Enter start time ([hh:mm] or [hhmm]), leave blank for an all-day event:",
			       buf, sizeof(buf)))
			return;
		if (!buf[0])
			break;
		if (parse_time(buf, &h, &m))
			break;
	}
	if (buf[0]) {
		start = update_time_in_date(sel_day, h, m);
		for (;;) {
			ebuf[0] = '\0';
			if (!getstring("Enter end time as date (and/or time) or duration ('?' for input formats):",
				       ebuf, sizeof(ebuf)))
				return;
			if (parse_end(ebuf, start, &end))
				break;
		}
	}
	if (!getstring("Enter description:", desc, sizeof(desc)) || !desc[0])
		return;
	if (buf[0]) {
		struct apoint *a = apoint_new(desc, NULL, start, end - start, 0);
		plist_add_sorted(&alist, a, apoint_cmp);
	} else {
		struct event *e = event_new(desc, NULL, sel_day, 1);
		plist_add_sorted(&elist, e, event_cmp);
	}
	modified = 1;
}

static void ui_add_todo(void)
{
	char buf[BUFSIZ_] = "";
	int ch, prio = 0;
	struct todo *t;

	if (!getstring("Enter the new TODO item:", buf, sizeof(buf)) || !buf[0])
		return;
	for (;;) {
		ch = getkey_prompt("Enter the TODO priority [0 (none), 1 (highest) - 9 (lowest)]:", "");
		if (ch >= '0' && ch <= '9') {
			prio = ch - '0';
			break;
		}
		if (ch == 27)
			return;
	}
	t = todo_new(buf, prio, 0, NULL);
	plist_add_sorted(&tlist, t, todo_cmp);
	modified = 1;
}

static int plist_index(struct plist *l, void *p)
{
	int i;
	for (i = 0; i < l->n; i++)
		if (l->v[i] == p)
			return i;
	return -1;
}

static void ui_delete_item(void)
{
	if (sel_panel == PANEL_APP) {
		time_t day;
		int k, idx, total = 0, ch;
		struct day_item *it = NULL;

		if (!app_item_day(app_sel, &day))
			return;
		/* locate the item */
		{
			time_t d = app_first;
			for (k = 0; k < 60; k++) {
				int n;
				day_store_items(d, 1);
				n = day_item_count();
				if (app_sel < total + n) {
					it = day_get_item(app_sel - total);
					break;
				}
				total += n;
				d = date_sec_change(d, 0, 1);
			}
		}
		if (!it)
			return;
		if (conf.confirm_delete) {
			ch = getkey_prompt("Confirm deletion. Delete (s)elected occurrence? Press (s) to confirm.",
					   "[s]");
			if (ch != 's')
				return;
		}
		switch (it->type) {
		case DI_APPT:
			idx = plist_index(&alist, it->item);
			if (idx >= 0)
				plist_remove(&alist, idx);
			break;
		case DI_EVNT:
			idx = plist_index(&elist, it->item);
			if (idx >= 0)
				plist_remove(&elist, idx);
			break;
		case DI_RECUR_APPT: {
			struct recur_apoint *r = it->item;
			ilist_add(&r->rpt.exc, (long)update_time_in_date(it->start, 0, 0));
			break;
		}
		case DI_RECUR_EVNT: {
			struct recur_event *r = it->item;
			ilist_add(&r->rpt.exc, (long)day);
			break;
		}
		}
		if (app_sel > 0)
			app_sel--;
		modified = 1;
	} else if (sel_panel == PANEL_TODO) {
		int ch;
		if (todo_sel >= tlist.n)
			return;
		if (conf.confirm_delete) {
			ch = getkey_prompt("Do you really want to delete this task?",
					   "[y/n]");
			if (ch != 'y')
				return;
		}
		plist_remove(&tlist, todo_sel);
