/* Date parsing relative to the selected day (fields may be omitted). */
static int parse_date_rel(const char *str, int *py, int *pm, int *pd)
{
	const char sep = conf.input_datefmt == DATEFMT_ISO ? '-' : '/';
	const char *p;
	long in[3] = { 0, 0, 0 };
	int n = 0, y, m, d, sy, sm, sd;

	for (p = str; *p; p++) {
		if (*p == sep) {
			if (++n > 2)
				return 0;
		} else if (*p >= '0' && *p <= '9') {
			in[n] = in[n] * 10 + (*p - '0');
			if (in[n] > 100000)
				return 0;
		} else {
			return 0;
		}
	}
	if (in[n] == 0)
		return 0;
	{
		struct tm lt;
		localtime_r(&sel_day, &lt);
		sy = lt.tm_year + 1900;
		sm = lt.tm_mon + 1;
		sd = lt.tm_mday;
	}
	(void)sd;
	switch (conf.input_datefmt) {
	case DATEFMT_MMDDYYYY:
		m = n >= 1 ? (int)in[0] : 0;
		d = n >= 1 ? (int)in[1] : (int)in[0];
		y = (int)in[2];
		break;
	case DATEFMT_DDMMYYYY:
		d = (int)in[0];
		m = (int)in[1];
		y = (int)in[2];
		break;
	default:
		y = (int)in[0];
		m = (int)in[1];
		d = (int)in[2];
		if (n == 0) {
			d = (int)in[0];
			y = 0;
		} else if (n == 1) {
			m = (int)in[0];
			d = (int)in[1];
			y = 0;
		}
		break;
	}
	if (y > 0 && y < 100)
		y += sy - sy % 100;
	else if (n < 2) {
		y = sy;
		if (n == 0)
			m = sm;
	}
	if (!check_date(y, m, d))
		return 0;
	*py = y;
	*pm = m;
	*pd = d;
	return 1;
}

